const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, viewport-fit=cover\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n<meta name=\"mobile-web-app-capable\" content=\"yes\">\n<meta name=\"theme-color\" content=\"#22331F\">\n<title>MizanKhata — Day, Work &amp; Shop</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Source+Serif+4:opsz,wght@8..60,400;8..60,600;8..60,700&family=IBM+Plex+Sans:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<script src=\"https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.min.js\"></script>\n<style>\n  :root{\n    --bg: #EEEBE3; --paper: #FBF9F4; --ink: #22271F; --ink-soft: #5B6156;\n    --forest: #2F4A34; --forest-deep: #1C2E20; --gold: #B8892B; --line: #DCD6C7;\n    --danger: #8C3B2E; --radius: 18px;\n  }\n  *{box-sizing:border-box; -webkit-tap-highlight-color: transparent;}\n  html,body{margin:0; padding:0; height:100%;}\n  body{ background: var(--bg); color: var(--ink); font-family: 'IBM Plex Sans', sans-serif; display:flex; justify-content:center; }\n  #app{ width:100%; max-width:480px; min-height:100vh; display:flex; flex-direction:column; background: var(--bg); padding-bottom: 84px; position:relative; }\n  header{ padding: 28px 22px 14px; }\n  .day-label{ font-size:13px; letter-spacing:0.02em; color: var(--ink-soft); }\n  h1{ font-family:'Source Serif 4', serif; font-weight:600; font-size:28px; margin: 2px 0 0; color: var(--forest-deep); }\n  main{ padding: 6px 18px 18px; flex:1; }\n  .card{ background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius); padding: 20px; margin-bottom: 16px; }\n\n  .timer-card{ text-align:center; padding: 32px 20px; }\n  .elapsed{ font-family:'Source Serif 4', serif; font-size: 46px; font-weight:600; color: var(--forest-deep); margin: 4px 0 22px; font-variant-numeric: tabular-nums; }\n  .timer-hint{ color: var(--ink-soft); font-size: 14px; margin-bottom: 6px;}\n  .btn-round{ width: 128px; height: 128px; border-radius: 50%; border: none; font-size: 17px; font-weight:600; color: #fff; background: var(--forest); cursor:pointer; transition: transform .12s ease; }\n  .btn-round:active{ transform: scale(0.95); }\n  .btn-round.running{ background: var(--danger); }\n\n  .today-total{ display:flex; justify-content:space-between; align-items:baseline; margin-bottom: 4px; }\n  .today-total .label{ font-size:14px; color:var(--ink-soft); }\n  .today-total .value{ font-family:'Source Serif 4', serif; font-size:22px; font-weight:600; color:var(--forest-deep); }\n\n  .session{ display:flex; justify-content:space-between; gap:12px; padding: 12px 0; border-top: 1px solid var(--line); }\n  .session:first-of-type{ border-top:none; }\n  .session .meta{ font-size:13px; color:var(--ink-soft); margin-top:2px;}\n  .session .dur{ font-weight:600; white-space:nowrap; }\n  .session .note{ font-size:14px; margin-top:3px; color:var(--ink); }\n  .empty-note{ color: var(--ink-soft); font-size:14px; text-align:center; padding:8px 0 4px;}\n\n  .section-title{ font-family:'Source Serif 4', serif; font-size:16px; font-weight:600; color: var(--forest-deep); margin: 18px 4px 8px; }\n  .section-title:first-child{ margin-top:2px; }\n  .routine-item{ display:flex; align-items:center; gap:12px; background: var(--paper); border:1px solid var(--line); border-radius: 14px; padding: 13px 14px; margin-bottom: 8px; }\n  .routine-item.done{ opacity: 0.5; }\n  .check{ width: 24px; height:24px; border-radius:50%; border: 2px solid var(--forest); flex-shrink:0; display:flex; align-items:center; justify-content:center; cursor:pointer; }\n  .check.checked{ background: var(--forest); }\n  .check.checked::after{ content:'✓'; color:#fff; font-size:14px; }\n  .routine-text{ flex:1; }\n  .routine-text .name{ font-size:15px; font-weight:500; }\n  .routine-text .time{ font-size:13px; color: var(--ink-soft); }\n  .routine-item.done .name{ text-decoration: line-through; }\n\n  .product-row{ display:flex; justify-content:space-between; align-items:center; padding:12px 0; border-top:1px solid var(--line); }\n  .product-row:first-child{ border-top:none; }\n  .product-row .pname{ font-size:15px; }\n  .product-row .psub{ font-size:12.5px; color:var(--ink-soft); margin-top:2px; }\n  .product-row .pqty{ font-family:'Source Serif 4', serif; font-weight:600; color:var(--forest-deep); font-size:17px; text-align:right; }\n\n  .product-grid{ display:grid; grid-template-columns: repeat(2, 1fr); gap:10px; }\n  .product-btn{ background: var(--bg); border:1px solid var(--line); border-radius:14px; padding:14px 10px; text-align:left; cursor:pointer; }\n  .product-btn:disabled{ cursor:not-allowed; }\n  .product-btn .pname{ font-weight:600; font-size:14px; }\n  .product-btn .pprice{ font-size:12px; color:var(--ink-soft); margin-top:2px; }\n  .cart-row{ display:flex; justify-content:space-between; align-items:center; padding:10px 0; border-top:1px solid var(--line); }\n  .cart-row:first-child{ border-top:none; }\n  .qty-controls{ display:flex; align-items:center; gap:10px; }\n  .qty-btn{ width:26px;height:26px;border-radius:50%;border:1px solid var(--forest); background:none; color:var(--forest); font-size:16px; cursor:pointer; display:flex;align-items:center;justify-content:center; }\n  .cart-total-row{ display:flex;justify-content:space-between; padding-top:12px; margin-top:6px; border-top:2px solid var(--line); font-weight:600; }\n  .btn-complete{ width:100%; margin-top:14px; padding:14px; border:none; border-radius:12px; background:var(--forest); color:#fff; font-weight:600; font-size:15px; cursor:pointer; }\n  .gear-btn{ background:none;border:none;font-size:20px;cursor:pointer;color:var(--ink-soft); }\n  .bill-card{ border-top:1px solid var(--line); padding:12px 0; }\n  .bill-card:first-child{ border-top:none; }\n  .bill-items{ font-size:13px; color:var(--ink-soft); margin-top:2px; }\n  .bill-head{ display:flex;justify-content:space-between; }\n  .bill-actions{ display:flex; gap:8px; margin-top:8px; }\n  .icon-btn{ background:none;border:1px solid var(--line); border-radius:10px; width:36px;height:34px; font-size:15px; cursor:pointer; display:flex;align-items:center;justify-content:center; color:var(--ink-soft); }\n  .product-row-manage{ display:flex; justify-content:space-between; align-items:center; padding:10px 0; border-top:1px solid var(--line); }\n  .product-row-manage:first-child{ border-top:none; }\n  .manage-actions button{ background:none;border:none;color:var(--danger); font-size:13px; cursor:pointer; text-decoration:underline; }\n\n  .stock-card{ border-top:1px solid var(--line); padding:12px 0; }\n  .stock-card:first-child{ border-top:none; }\n  .stock-head{ display:flex; justify-content:space-between; align-items:baseline; }\n  .stock-head .pname{ font-weight:600; font-size:15px; }\n  .stock-head .qty{ font-family:'Source Serif 4', serif; font-weight:600; color:var(--forest-deep); font-size:18px; }\n  .stock-sub{ font-size:12.5px; color:var(--ink-soft); margin-top:3px; display:flex; gap:12px; flex-wrap:wrap; }\n  .purchase-log-row{ display:flex; justify-content:space-between; padding:9px 0; border-top:1px solid var(--line); font-size:13px; }\n  .purchase-log-row:first-child{ border-top:none; }\n  .tag-low{ background:#F6E4E0; color:var(--danger); font-size:11px; padding:2px 8px; border-radius:8px; margin-left:8px; }\n  .form-label{ font-size:12px; color:var(--ink-soft); margin:0 0 4px 2px; display:block; }\n  .toggle-btn{ flex:1; padding:10px; border-radius:10px; border:1px solid var(--line); background:var(--paper); color:var(--ink); font-family:'IBM Plex Sans'; font-size:13px; cursor:pointer; }\n  .toggle-btn.active{ background:var(--forest); color:#fff; border-color:var(--forest); }\n  .select-field, .sheet input[type=text], .sheet input[type=number]{ width:100%; border:1px solid var(--line); border-radius:10px; padding:11px; font-family:'IBM Plex Sans'; font-size:14px; margin-bottom:12px; background:#fff; }\n  .receipt-preview{ width:100%; border-radius:12px; border:1px solid var(--line); margin-bottom:14px; display:block; }\n\n  .subtab-row{ display:flex; gap:8px; margin-bottom:14px; }\n  .subtab-btn{ flex:1; padding:10px; border-radius:10px; border:1px solid var(--line); background:var(--paper); color:var(--ink-soft); font-family:'IBM Plex Sans'; font-size:13px; font-weight:600; cursor:pointer; }\n  .subtab-btn.active{ background:var(--forest-deep); color:#fff; border-color:var(--forest-deep); }\n  .customer-row{ display:flex; justify-content:space-between; align-items:center; padding:12px 0; border-top:1px solid var(--line); cursor:pointer; }\n  .customer-row:first-child{ border-top:none; }\n  .customer-row .cname{ font-size:15px; font-weight:600; }\n  .customer-row .cphone{ font-size:12px; color:var(--ink-soft); margin-top:2px; }\n  .customer-row .cbal{ font-family:'Source Serif 4', serif; font-weight:600; font-size:16px; text-align:right; }\n  .cbal.owe{ color: var(--danger); }\n  .cbal.clear{ color: var(--ink-soft); font-weight:400; font-size:13px; }\n  .cash-row{ display:flex; justify-content:space-between; align-items:center; padding:11px 0; border-top:1px solid var(--line); font-size:14px; }\n  .cash-row:first-child{ border-top:none; }\n  .cash-row .cnote{ font-size:12px; color:var(--ink-soft); margin-top:2px; }\n  .camt.in{ color: var(--forest-deep); font-weight:600; }\n  .camt.out{ color: var(--danger); font-weight:600; }\n  .btn-whatsapp{ background:#25D366; color:#fff; text-decoration:none; display:flex; align-items:center; justify-content:center; }\n  .tx-row{ display:flex; justify-content:space-between; padding:9px 0; border-top:1px solid var(--line); font-size:13.5px; }\n  .tx-row:first-child{ border-top:none; }\n  .pay-badge{ display:inline-block; font-size:11px; padding:2px 8px; border-radius:8px; margin-top:5px; }\n  .pay-badge.cash{ background:#E3ECE4; color:var(--forest-deep); }\n  .pay-badge.credit{ background:#F6E4E0; color:var(--danger); }\n  .pay-badge.partial{ background:#FBF3DD; color:#6B4E12; }\n  .calc-row-wrap{ display:flex; align-items:center; gap:8px; margin-bottom:8px; }\n  .calc-row-wrap input{ margin-bottom:0 !important; flex:1; }\n  .calc-toggle{ background:var(--bg); border:1px solid var(--line); border-radius:8px; width:38px; height:38px; font-size:16px; cursor:pointer; color:var(--ink-soft); flex-shrink:0; }\n  .calc-pad{ display:none; grid-template-columns: repeat(4,1fr); gap:7px; margin-bottom:12px; }\n  .calc-pad.open{ display:grid; }\n  .calc-key{ padding:11px 0; border-radius:9px; border:1px solid var(--line); background:var(--paper); font-family:'IBM Plex Sans'; font-size:15px; cursor:pointer; text-align:center; color:var(--ink); }\n  .calc-key.op{ background:var(--bg); color:var(--forest-deep); font-weight:600; }\n  .calc-key.eq{ background:var(--forest); color:#fff; font-weight:600; }\n  .calc-key.ac{ background:#F6E4E0; color:var(--danger); font-weight:600; }\n  .calc-key.wide{ grid-column: span 2; }\n\n  .fab-wrap{ position:fixed; bottom:78px; left:0; right:0; display:flex; justify-content:center; pointer-events:none; z-index:15; }\n  .fab-inner{ width:100%; max-width:480px; display:flex; justify-content:flex-end; padding-right:20px; }\n  .fab{ pointer-events:auto; width:58px;height:58px;border-radius:50%; background:var(--forest); color:#fff; border:none; font-size:28px; line-height:1; box-shadow:0 6px 16px rgba(28,46,32,.35); cursor:pointer; }\n\n  nav{ position: fixed; bottom:0; left:0; right:0; display:flex; justify-content:center; background: var(--forest-deep); padding-bottom: env(safe-area-inset-bottom); }\n  .nav-inner{ width:100%; max-width:480px; display:flex; }\n  .nav-btn{ flex:1; background:none; border:none; color: rgba(255,255,255,0.55); font-size:12.5px; padding: 14px 0 12px; cursor:pointer; }\n  .nav-btn.active{ color: var(--gold); font-weight:600; }\n  .nav-btn .dot{ display:block; width:6px; height:6px; border-radius:50%; background:transparent; margin:0 auto 5px; }\n  .nav-btn.active .dot{ background: var(--gold); }\n\n  .sheet-backdrop{ position:fixed; inset:0; background:rgba(28,46,32,0.45); display:flex; align-items:flex-end; justify-content:center; z-index:20; }\n  .sheet{ width:100%; max-width:480px; background: var(--paper); border-radius: 22px 22px 0 0; padding: 22px 20px calc(22px + env(safe-area-inset-bottom)); max-height: 85vh; overflow-y:auto; }\n  .sheet h2{ font-family:'Source Serif 4', serif; font-size:19px; margin:0 0 4px; color:var(--forest-deep);}\n  .sheet p{ font-size:13px; color:var(--ink-soft); margin:0 0 14px;}\n  .sheet textarea{ width:100%; min-height:80px; border:1px solid var(--line); border-radius:12px; padding:12px; font-family:'IBM Plex Sans'; font-size:15px; resize:none; margin-bottom:14px; }\n  .sheet-actions{ display:flex; gap:10px; }\n  .sheet-actions button{ flex:1; padding:13px; border-radius:12px; border:none; font-family:'IBM Plex Sans'; font-size:15px; font-weight:600; cursor:pointer; }\n  .btn-save{ background: var(--forest); color:#fff; }\n  .btn-skip{ background: var(--line); color: var(--ink); }\n\n  .toast{ position:fixed; top:16px; left:50%; transform:translateX(-50%); background: var(--forest-deep); color:#fff; padding:11px 18px; border-radius:12px; font-size:14px; z-index:30; opacity:0; transition:opacity .3s ease; max-width: 90%; text-align:center; }\n  .toast.show{ opacity:1; }\n  .banner{ background: #FBF3DD; border:1px solid var(--gold); color: #6B4E12; border-radius:14px; padding:12px 14px; font-size:13px; margin-bottom:14px; display:none; }\n\n  #authScreen{ width:100%; max-width:480px; min-height:100vh; display:flex; flex-direction:column; justify-content:center; padding:28px 24px; background:var(--bg); }\n  #authScreen h1{ text-align:center; margin-bottom:4px; }\n  #authScreen .auth-sub{ text-align:center; color:var(--ink-soft); font-size:14px; margin-bottom:28px; }\n  #authScreen input{ width:100%; border:1px solid var(--line); border-radius:10px; padding:13px; font-family:'IBM Plex Sans'; font-size:15px; margin-bottom:12px; background:#fff; }\n  #authScreen .btn-save{ width:100%; padding:14px; }\n  #authScreen .auth-toggle{ text-align:center; margin-top:16px; font-size:13.5px; color:var(--ink-soft); }\n  #authScreen .auth-toggle a{ color:var(--forest-deep); font-weight:600; text-decoration:underline; cursor:pointer; }\n  #authScreen .auth-error{ color:var(--danger); font-size:13px; margin:-4px 0 12px; display:none; }\n  #signOutBtn{ background:none; border:none; color:var(--ink-soft); font-size:12px; text-decoration:underline; cursor:pointer; }\n</style>\n</head>\n<body>\n<div id=\"authScreen\" style=\"display:none;\">\n  <h1>MizanKhata</h1>\n  <div class=\"auth-sub\">Sign in to your shop account</div>\n  <div class=\"auth-error\" id=\"authError\"></div>\n  <input type=\"email\" id=\"authEmail\" placeholder=\"Email\" autocomplete=\"username\">\n  <input type=\"password\" id=\"authPassword\" placeholder=\"Password\" autocomplete=\"current-password\">\n  <button class=\"btn-save\" id=\"authSubmitBtn\">Sign in</button>\n  <div class=\"auth-toggle\" id=\"authToggleWrap\">New here? <a id=\"authToggleLink\">Create an account</a></div>\n</div>\n\n<div id=\"app\" style=\"display:none;\">\n  <header>\n    <div class=\"day-label\" id=\"dayLabel\">Today</div>\n    <h1 id=\"pageTitle\">Work</h1>\n    <button id=\"signOutBtn\">Sign out</button>\n  </header>\n\n  <main>\n    <div class=\"banner\" id=\"notifyBanner\">\n      Turn on notifications so routine reminders can pop up while this page is open. <span id=\"notifyBtn\" style=\"text-decoration:underline; cursor:pointer;\">Enable</span>\n    </div>\n\n    <div id=\"workTab\">\n      <div class=\"card timer-card\">\n        <div class=\"timer-hint\" id=\"timerHint\">Not working right now</div>\n        <div class=\"elapsed\" id=\"elapsed\">00:00:00</div>\n        <button class=\"btn-round\" id=\"toggleBtn\">Start work</button>\n      </div>\n      <div class=\"card\">\n        <div class=\"today-total\"><span class=\"label\">Worked today</span><span class=\"value\" id=\"totalToday\">0h 0m</span></div>\n      </div>\n      <div class=\"card\" id=\"sessionsCard\">\n        <div class=\"section-title\" style=\"margin-top:0;\">Today's sessions</div>\n        <div id=\"sessionsList\"></div>\n      </div>\n    </div>\n\n    <div id=\"routineTab\" style=\"display:none;\"></div>\n    <div id=\"salesTab\" style=\"display:none;\"></div>\n    <div id=\"stockTab\" style=\"display:none;\"></div>\n    <div id=\"ledgerTab\" style=\"display:none;\"></div>\n  </main>\n\n  <nav>\n    <div class=\"nav-inner\">\n      <button class=\"nav-btn active\" data-tab=\"work\"><span class=\"dot\"></span>Work</button>\n      <button class=\"nav-btn\" data-tab=\"routine\"><span class=\"dot\"></span>Routine</button>\n      <button class=\"nav-btn\" data-tab=\"sales\"><span class=\"dot\"></span>Sales</button>\n      <button class=\"nav-btn\" data-tab=\"stock\"><span class=\"dot\"></span>Stock</button>\n      <button class=\"nav-btn\" data-tab=\"ledger\"><span class=\"dot\"></span>Ledger</button>\n    </div>\n  </nav>\n</div>\n\n<div id=\"sheetLayer\"></div>\n<div class=\"toast\" id=\"toast\"></div>\n<input type=\"file\" id=\"photoInput\" accept=\"image/*\" capture=\"environment\" style=\"display:none\">\n\n<script>\nconst SUPABASE_URL = \"https://fksdpsecfnaibquymiir.supabase.co\";\nconst SUPABASE_ANON_KEY = \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImZrc2Rwc2VjZm5haWJxdXltaWlyIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODg5MjY1MDMsImV4cCI6MjEwNDUwMjUwM30.dny1Fpf0XdLYqZcFUxAvvFD9I53MlFY6nSQCA3tw-1o\";\nconst sb = supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);\nlet authMode = \"signin\";\n\nfunction showAuthScreen(){\n  document.getElementById(\"authScreen\").style.display = \"flex\";\n  document.getElementById(\"app\").style.display = \"none\";\n}\nfunction showApp(){\n  document.getElementById(\"authScreen\").style.display = \"none\";\n  document.getElementById(\"app\").style.display = \"flex\";\n}\nfunction setAuthError(msg){\n  const el = document.getElementById(\"authError\");\n  el.textContent = msg;\n  el.style.display = msg ? \"block\" : \"none\";\n}\ndocument.getElementById(\"authToggleWrap\").addEventListener(\"click\", (e)=>{\n  if(e.target.tagName !== \"A\") return;\n  authMode = authMode === \"signin\" ? \"signup\" : \"signin\";\n  document.getElementById(\"authSubmitBtn\").textContent = authMode === \"signin\" ? \"Sign in\" : \"Create account\";\n  document.getElementById(\"authToggleWrap\").innerHTML = authMode === \"signin\"\n    ? 'New here? <a>Create an account</a>'\n    : 'Already have an account? <a>Sign in</a>';\n  setAuthError(\"\");\n});\ndocument.getElementById(\"authSubmitBtn\").addEventListener(\"click\", async ()=>{\n  const email = document.getElementById(\"authEmail\").value.trim();\n  const password = document.getElementById(\"authPassword\").value;\n  if(!email || !password){ setAuthError(\"Enter both email and password\"); return; }\n  setAuthError(\"\");\n  const btn = document.getElementById(\"authSubmitBtn\");\n  btn.textContent = \"Please wait...\";\n  try{\n    if(authMode === \"signin\"){\n      const {error} = await sb.auth.signInWithPassword({email, password});\n      if(error){ setAuthError(error.message); btn.textContent = \"Sign in\"; return; }\n    } else {\n      const {error} = await sb.auth.signUp({email, password});\n      if(error){ setAuthError(error.message); btn.textContent = \"Create account\"; return; }\n    }\n    await startApp();\n  }catch(e){\n    setAuthError(\"Something went wrong — try again\");\n    btn.textContent = authMode === \"signin\" ? \"Sign in\" : \"Create account\";\n  }\n});\ndocument.getElementById(\"signOutBtn\").addEventListener(\"click\", async ()=>{\n  await sb.auth.signOut();\n  showAuthScreen();\n});\n\nconst ROUTINE = [\n  {section:\"Prayer\", items:[\n    {id:\"fajr\", name:\"Fajr\", time:\"05:30\"},\n    {id:\"dhuhr\", name:\"Dhuhr\", time:\"13:30\"},\n    {id:\"asr\", name:\"Asr\", time:\"17:00\"},\n    {id:\"maghrib\", name:\"Maghrib\", time:\"19:00\"},\n    {id:\"isha\", name:\"Isha\", time:\"21:00\"},\n  ]},\n  {section:\"Work\", items:[\n    {id:\"deepwork\", name:\"Deep work block\", time:\"09:00\"},\n    {id:\"studyblock\", name:\"Study / learning block\", time:\"15:00\"},\n  ]},\n  {section:\"Health\", items:[\n    {id:\"gym\", name:\"Gym\", time:\"06:30\"},\n    {id:\"water1\", name:\"Drink water\", time:\"10:00\"},\n    {id:\"break1\", name:\"Short break\", time:\"11:00\"},\n    {id:\"water2\", name:\"Drink water\", time:\"14:00\"},\n    {id:\"break2\", name:\"Short break\", time:\"16:00\"},\n    {id:\"water3\", name:\"Drink water\", time:\"18:00\"},\n    {id:\"winddown\", name:\"Wind down / sleep prep\", time:\"22:30\"},\n  ]},\n];\nconst UNIT_LABELS = {pcs:'pieces', kg:'kg', g:'grams', litre:'litres', dozen:'dozens', box:'boxes'};\n\nfunction todayKey(){\n  const d = new Date();\n  return d.getFullYear()+\"-\"+String(d.getMonth()+1).padStart(2,\"0\")+\"-\"+String(d.getDate()).padStart(2,\"0\");\n}\nfunction fmtClock(ms){\n  const s = Math.floor(ms/1000);\n  const h = String(Math.floor(s/3600)).padStart(2,\"0\");\n  const m = String(Math.floor((s%3600)/60)).padStart(2,\"0\");\n  const sec = String(s%60).padStart(2,\"0\");\n  return h+\":\"+m+\":\"+sec;\n}\nfunction fmtHM(ms){\n  const mins = Math.round(ms/60000);\n  return Math.floor(mins/60)+\"h \"+(mins%60)+\"m\";\n}\nfunction fmtTimeLabel(iso){\n  const d = new Date(iso);\n  return d.toLocaleTimeString([], {hour:'numeric', minute:'2-digit'});\n}\nfunction formatQty(qty, unit){\n  const q = Number(qty) || 0;\n  const qtyStr = Number.isInteger(q) ? q.toString() : q.toFixed(2).replace(/0+$/,'').replace(/\\.$/,'');\n  return `${qtyStr} ${unit || 'pcs'}`;\n}\nfunction unitStep(unit){\n  return (unit === 'kg' || unit === 'litre' || unit === 'g') ? 0.5 : 1;\n}\nasync function localGet(key){\n  try{ const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) : null; }\n  catch(e){ return null; }\n}\nasync function localSet(key, value){\n  try{ localStorage.setItem(key, JSON.stringify(value)); }\n  catch(e){ console.error(\"save failed\", e); showToast(\"Couldn't save — try again\"); }\n}\n\n/* ---- Supabase row <-> app object mappers ---- */\nfunction custRowToObj(r){ return {id:r.id, name:r.name, phone:r.phone||\"\"}; }\nfunction prodRowToObj(r){ return {id:r.id, name:r.name, unit:r.unit||\"pcs\", salePrice:Number(r.sale_price), stock:Number(r.stock)}; }\nfunction purchRowToObj(r){ return {id:r.id, productId:r.product_id, qty:Number(r.qty), price:Number(r.price), ref:r.ref||\"\", date:r.date}; }\nfunction khataRowToObj(r){ return {id:r.id, customerId:r.customer_id, type:r.type, amount:Number(r.amount), note:r.note||\"\", ref:r.ref||\"\", billId:r.bill_id, date:r.date}; }\nfunction supTxRowToObj(r){ return {id:r.id, supplierId:r.supplier_id, type:r.type, amount:Number(r.amount), note:r.note||\"\", ref:r.ref||\"\", date:r.date}; }\nfunction cashRowToObj(r){ return {id:r.id, type:r.type, amount:Number(r.amount), note:r.note||\"\", partyType:r.party_type, partyId:r.party_id, partyName:r.party_name, date:r.date}; }\n\nasync function sbFetchSimple(table){\n  const {data, error} = await sb.from(table).select(\"*\").order(\"created_at\");\n  if(error){ console.error(error); showToast(\"Couldn't load data\"); return []; }\n  return data.map(custRowToObj);\n}\nasync function sbSyncSimple(table, arr){\n  if(!arr.length) return;\n  const {error} = await sb.from(table).upsert(arr.map(x=>({id:x.id, name:x.name, phone:x.phone||null})));\n  if(error){ console.error(error); showToast(\"Couldn't save — try again\"); }\n}\nasync function sbFetchProducts(){\n  const {data, error} = await sb.from(\"shop_products\").select(\"*\").order(\"created_at\");\n  if(error){ console.error(error); showToast(\"Couldn't load products\"); return []; }\n  return data.map(prodRowToObj);\n}\nasync function sbSyncProducts(arr){\n  if(!arr.length) return;\n  const {error} = await sb.from(\"shop_products\").upsert(arr.map(p=>({id:p.id, name:p.name, unit:p.unit||\"pcs\", sale_price:p.salePrice, stock:p.stock})));\n  if(error){ console.error(error); showToast(\"Couldn't save — try again\"); }\n}\nasync function sbDeleteRow(table, id){\n  const {error} = await sb.from(table).delete().eq(\"id\", id);\n  if(error){ console.error(error); showToast(\"Couldn't delete — try again\"); }\n}\nasync function sbFetchPurchases(){\n  const {data, error} = await sb.from(\"shop_purchases\").select(\"*\").order(\"date\");\n  if(error){ console.error(error); showToast(\"Couldn't load purchases\"); return []; }\n  return data.map(purchRowToObj);\n}\nasync function sbSyncPurchases(arr){\n  if(!arr.length) return;\n  const {error} = await sb.from(\"shop_purchases\").upsert(arr.map(p=>({id:p.id, product_id:p.productId, qty:p.qty, price:p.price, ref:p.ref||null, date:p.date})));\n  if(error){ console.error(error); showToast(\"Couldn't save — try again\"); }\n}\nasync function sbFetchKhataTx(){\n  const {data, error} = await sb.from(\"shop_khata_tx\").select(\"*\").order(\"date\");\n  if(error){ console.error(error); showToast(\"Couldn't load ledger\"); return []; }\n  return data.map(khataRowToObj);\n}\nasync function sbSyncKhataTx(arr){\n  if(!arr.length) return;\n  const {error} = await sb.from(\"shop_khata_tx\").upsert(arr.map(t=>({id:t.id, customer_id:t.customerId, type:t.type, amount:t.amount, note:t.note||null, ref:t.ref||null, bill_id:t.billId||null, date:t.date})));\n  if(error){ console.error(error); showToast(\"Couldn't save — try again\"); }\n}\nasync function sbFetchSupplierTx(){\n  const {data, error} = await sb.from(\"shop_supplier_tx\").select(\"*\").order(\"date\");\n  if(error){ console.error(error); showToast(\"Couldn't load ledger\"); return []; }\n  return data.map(supTxRowToObj);\n}\nasync function sbSyncSupplierTx(arr){\n  if(!arr.length) return;\n  const {error} = await sb.from(\"shop_supplier_tx\").upsert(arr.map(t=>({id:t.id, supplier_id:t.supplierId, type:t.type, amount:t.amount, note:t.note||null, ref:t.ref||null, date:t.date})));\n  if(error){ console.error(error); showToast(\"Couldn't save — try again\"); }\n}\nasync function sbFetchCashbook(){\n  const {data, error} = await sb.from(\"shop_cashbook\").select(\"*\").order(\"date\");\n  if(error){ console.error(error); showToast(\"Couldn't load cash book\"); return []; }\n  return data.map(cashRowToObj);\n}\nasync function sbSyncCashbook(arr){\n  if(!arr.length) return;\n  const {error} = await sb.from(\"shop_cashbook\").upsert(arr.map(e=>({id:e.id, type:e.type, amount:e.amount, note:e.note||null, party_type:e.partyType||null, party_id:e.partyId||null, party_name:e.partyName||null, date:e.date})));\n  if(error){ console.error(error); showToast(\"Couldn't save — try again\"); }\n}\nasync function sbFetchSalesForDate(dateKey){\n  const {data, error} = await sb.from(\"shop_sales\").select(\"*, shop_sale_items(*)\").gte(\"time\", dateKey+\"T00:00:00\").lte(\"time\", dateKey+\"T23:59:59.999\").order(\"time\");\n  if(error){ console.error(error); showToast(\"Couldn't load sales\"); return []; }\n  return data.map(r=>({\n    id:r.id, time:r.time, total:Number(r.total), paidCash:Number(r.paid_cash), creditAmount:Number(r.credit_amount),\n    customerId:r.customer_id, customerName:r.customer_name, hasPaperPhoto:r.has_paper_photo,\n    items:(r.shop_sale_items||[]).map(i=>({productId:i.product_id, name:i.name, unit:i.unit, price:Number(i.price), qty:Number(i.qty)}))\n  }));\n}\nasync function sbSyncSalesForDate(arr){\n  if(!arr.length) return;\n  const {error} = await sb.from(\"shop_sales\").upsert(arr.map(s=>({\n    id:s.id, time:s.time, total:s.total, paid_cash:s.paidCash, credit_amount:s.creditAmount,\n    customer_id:s.customerId||null, customer_name:s.customerName||null, has_paper_photo:!!s.hasPaperPhoto\n  })));\n  if(error){ console.error(error); showToast(\"Couldn't save sale\"); return; }\n  for(const s of arr){\n    await sb.from(\"shop_sale_items\").delete().eq(\"sale_id\", s.id);\n    if(s.items && s.items.length){\n      await sb.from(\"shop_sale_items\").insert(s.items.map(i=>({\n        id: s.id+\"-\"+Math.random().toString(36).slice(2,8), sale_id:s.id, product_id:i.productId||null, name:i.name, unit:i.unit||\"pcs\", price:i.price, qty:i.qty\n      })));\n    }\n  }\n}\n\n/* ---- Work sessions <-> shop_work_sessions ---- */\nfunction dayRangeIso(dateKey){\n  // local calendar day -> UTC instants, so near-midnight rows land on the right day\n  return {\n    from: new Date(dateKey + \"T00:00:00\").toISOString(),\n    to: new Date(dateKey + \"T23:59:59.999\").toISOString()\n  };\n}\nasync function sbFetchWorkSessions(dateKey){\n  const {from, to} = dayRangeIso(dateKey);\n  const {data, error} = await sb.from(\"shop_work_sessions\")\n    .select(\"*\").gte(\"start_time\", from).lte(\"start_time\", to).order(\"start_time\");\n  if(error){ console.error(error); showToast(\"Couldn't load sessions\"); return []; }\n  return data.map(r=>({id:r.id, start:r.start_time, end:r.end_time, durationMs:Number(r.duration_ms), note:r.note||\"\"}));\n}\nasync function sbSyncWorkSessions(arr){\n  if(!arr.length) return;\n  const {error} = await sb.from(\"shop_work_sessions\").upsert(arr.map(s=>({\n    id:s.id, start_time:s.start, end_time:s.end, duration_ms:s.durationMs, note:s.note||null\n  })));\n  if(error){ console.error(error); showToast(\"Couldn't save session\"); }\n}\n\n/* ---- Daily routine <-> shop_routine_state (one row per checked item) ---- */\nasync function sbFetchRoutine(dateKey){\n  const {data, error} = await sb.from(\"shop_routine_state\").select(\"item_id, done\").eq(\"date\", dateKey);\n  if(error){ console.error(error); showToast(\"Couldn't load routine\"); return {}; }\n  const out = {};\n  (data||[]).forEach(r=>{ out[r.item_id] = r.done; });\n  return out;\n}\nasync function sbSyncRoutine(dateKey, obj){\n  const upserts = [], deletes = [];\n  Object.keys(obj || {}).forEach(itemId=>{\n    if(obj[itemId]) upserts.push({id: dateKey + \"-\" + itemId, date: dateKey, item_id: itemId, done: true});\n    else deletes.push(dateKey + \"-\" + itemId);\n  });\n  if(upserts.length){\n    const {error} = await sb.from(\"shop_routine_state\").upsert(upserts);\n    if(error){ console.error(error); showToast(\"Couldn't save — try again\"); }\n  }\n  for(const id of deletes){\n    await sb.from(\"shop_routine_state\").delete().eq(\"id\", id);\n  }\n}\n\nasync function storeGet(key){\n  if(key === \"pos-products\") return await sbFetchProducts();\n  if(key === \"purchases\") return await sbFetchPurchases();\n  if(key === \"khata-customers\") return await sbFetchSimple(\"shop_customers\");\n  if(key === \"khata-suppliers\") return await sbFetchSimple(\"shop_suppliers\");\n  if(key === \"khata-tx\") return await sbFetchKhataTx();\n  if(key === \"supplier-tx\") return await sbFetchSupplierTx();\n  if(key === \"cashbook\") return await sbFetchCashbook();\n  if(key.startsWith(\"pos-sales:\")) return await sbFetchSalesForDate(key.slice(10));\n  if(key.startsWith(\"bill-photo:\")){\n    const {data, error} = await sb.from(\"shop_sales\").select(\"photo_data_url\").eq(\"id\", key.slice(11)).maybeSingle();\n    if(error || !data) return null;\n    return data.photo_data_url || null;\n  }\n  if(key.startsWith(\"work-sessions:\")) return await sbFetchWorkSessions(key.slice(14));\n  if(key.startsWith(\"routine:\")) return await sbFetchRoutine(key.slice(8));\n  return await localGet(key);\n}\nasync function storeSet(key, value){\n  if(key === \"pos-products\") return await sbSyncProducts(value);\n  if(key === \"purchases\") return await sbSyncPurchases(value);\n  if(key === \"khata-customers\") return await sbSyncSimple(\"shop_customers\", value);\n  if(key === \"khata-suppliers\") return await sbSyncSimple(\"shop_suppliers\", value);\n  if(key === \"khata-tx\") return await sbSyncKhataTx(value);\n  if(key === \"supplier-tx\") return await sbSyncSupplierTx(value);\n  if(key === \"cashbook\") return await sbSyncCashbook(value);\n  if(key.startsWith(\"pos-sales:\")) return await sbSyncSalesForDate(value);\n  if(key.startsWith(\"bill-photo:\")){\n    const {error} = await sb.from(\"shop_sales\").update({photo_data_url:value, has_paper_photo:true}).eq(\"id\", key.slice(11));\n    if(error){ console.error(error); showToast(\"Couldn't save photo\"); }\n    return;\n  }\n  if(key.startsWith(\"work-sessions:\")) return await sbSyncWorkSessions(value);\n  if(key.startsWith(\"routine:\")) return await sbSyncRoutine(key.slice(8), value);\n  return await localSet(key, value);\n}\nfunction showToast(msg){\n  const t = document.getElementById(\"toast\");\n  t.textContent = msg;\n  t.classList.add(\"show\");\n  setTimeout(()=>t.classList.remove(\"show\"), 2200);\n}\nfunction escapeHtml(str){\n  const d = document.createElement(\"div\");\n  d.textContent = str;\n  return d.innerHTML;\n}\nfunction calcFieldHtml(id, placeholder){\n  return `<div class=\"calc-row-wrap\">\n    <input type=\"text\" inputmode=\"decimal\" id=\"${id}\" placeholder=\"${placeholder||''}\">\n    <button type=\"button\" class=\"calc-toggle\" data-calc-for=\"${id}\">🖩</button>\n  </div>\n  <div class=\"calc-pad\" id=\"${id}_pad\">\n    <button type=\"button\" class=\"calc-key ac\" data-k=\"AC\">AC</button>\n    <button type=\"button\" class=\"calc-key op\" data-k=\"/\">÷</button>\n    <button type=\"button\" class=\"calc-key op\" data-k=\"*\">×</button>\n    <button type=\"button\" class=\"calc-key op\" data-k=\"back\">⌫</button>\n    <button type=\"button\" class=\"calc-key\" data-k=\"7\">7</button>\n    <button type=\"button\" class=\"calc-key\" data-k=\"8\">8</button>\n    <button type=\"button\" class=\"calc-key\" data-k=\"9\">9</button>\n    <button type=\"button\" class=\"calc-key op\" data-k=\"-\">−</button>\n    <button type=\"button\" class=\"calc-key\" data-k=\"4\">4</button>\n    <button type=\"button\" class=\"calc-key\" data-k=\"5\">5</button>\n    <button type=\"button\" class=\"calc-key\" data-k=\"6\">6</button>\n    <button type=\"button\" class=\"calc-key op\" data-k=\"+\">+</button>\n    <button type=\"button\" class=\"calc-key\" data-k=\"1\">1</button>\n    <button type=\"button\" class=\"calc-key\" data-k=\"2\">2</button>\n    <button type=\"button\" class=\"calc-key\" data-k=\"3\">3</button>\n    <button type=\"button\" class=\"calc-key eq\" data-k=\"=\" style=\"grid-row: span 2;\">=</button>\n    <button type=\"button\" class=\"calc-key wide\" data-k=\"0\">0</button>\n    <button type=\"button\" class=\"calc-key\" data-k=\".\">.</button>\n  </div>`;\n}\ndocument.getElementById(\"sheetLayer\").addEventListener(\"click\", (e)=>{\n  const toggleBtn = e.target.closest(\".calc-toggle\");\n  if(toggleBtn){\n    const pad = document.getElementById(toggleBtn.dataset.calcFor + \"_pad\");\n    if(pad) pad.classList.toggle(\"open\");\n    return;\n  }\n  const key = e.target.closest(\".calc-key\");\n  if(key){\n    const pad = key.closest(\".calc-pad\");\n    const inputId = pad.id.slice(0, -4);\n    const input = document.getElementById(inputId);\n    if(!input) return;\n    const k = key.dataset.k;\n    if(k === \"AC\"){ input.value = \"\"; }\n    else if(k === \"back\"){ input.value = input.value.slice(0, -1); }\n    else if(k === \"=\"){\n      try{\n        const expr = input.value.replace(/[^0-9+\\-*/.() ]/g, \"\");\n        if(expr.trim()){\n          const result = Function('\"use strict\"; return (' + expr + ')')();\n          if(isFinite(result)) input.value = (Math.round(result * 100) / 100).toString();\n        }\n      }catch(err){ /* ignore invalid expression */ }\n    } else {\n      input.value += k;\n    }\n  }\n});\n\n/* ---------- WORK TAB ---------- */\nlet running = null;\nlet sessions = [];\nlet tickHandle = null;\n\nasync function loadWork(){\n  running = await storeGet(\"work-running\");\n  sessions = (await storeGet(\"work-sessions:\"+todayKey())) || [];\n  renderWork();\n  if(running){ startTicking(); }\n}\nfunction renderWork(){\n  document.getElementById(\"toggleBtn\").textContent = running ? \"Stop work\" : \"Start work\";\n  document.getElementById(\"toggleBtn\").classList.toggle(\"running\", !!running);\n  document.getElementById(\"timerHint\").textContent = running ? \"Working since \" + fmtTimeLabel(running.start) : \"Not working right now\";\n  const totalMs = sessions.reduce((sum,s)=>sum+s.durationMs,0);\n  document.getElementById(\"totalToday\").textContent = fmtHM(totalMs);\n  const list = document.getElementById(\"sessionsList\");\n  if(sessions.length === 0){\n    list.innerHTML = '<div class=\"empty-note\">No sessions yet today</div>';\n  } else {\n    list.innerHTML = sessions.slice().reverse().map(s => `\n      <div class=\"session\">\n        <div>\n          <div class=\"meta\">${fmtTimeLabel(s.start)} – ${fmtTimeLabel(s.end)}</div>\n          ${s.note ? `<div class=\"note\">${escapeHtml(s.note)}</div>` : \"\"}\n        </div>\n        <div class=\"dur\">${fmtHM(s.durationMs)}</div>\n      </div>\n    `).join(\"\");\n  }\n}\nfunction startTicking(){\n  if(tickHandle) clearInterval(tickHandle);\n  tickHandle = setInterval(()=>{\n    if(!running) return;\n    document.getElementById(\"elapsed\").textContent = fmtClock(Date.now() - new Date(running.start).getTime());\n  }, 1000);\n}\nfunction stopTicking(){ if(tickHandle) clearInterval(tickHandle); document.getElementById(\"elapsed\").textContent = \"00:00:00\"; }\ndocument.getElementById(\"toggleBtn\").addEventListener(\"click\", async ()=>{\n  if(!running){\n    running = { start: new Date().toISOString() };\n    await storeSet(\"work-running\", running);\n    renderWork(); startTicking();\n  } else { openNoteSheet(); }\n});\nfunction openNoteSheet(){\n  const layer = document.getElementById(\"sheetLayer\");\n  layer.innerHTML = `\n    <div class=\"sheet-backdrop\"><div class=\"sheet\">\n      <h2>Nice work</h2>\n      <p>You worked ${fmtHM(Date.now() - new Date(running.start).getTime())}. Add a quick note about what you did?</p>\n      <textarea id=\"noteInput\" placeholder=\"e.g. Client emails, invoice follow-ups...\"></textarea>\n      <div class=\"sheet-actions\">\n        <button class=\"btn-skip\" id=\"skipNote\">Skip</button>\n        <button class=\"btn-save\" id=\"saveNote\">Save session</button>\n      </div>\n    </div></div>`;\n  document.getElementById(\"skipNote\").addEventListener(\"click\", ()=>finishSession(\"\"));\n  document.getElementById(\"saveNote\").addEventListener(\"click\", ()=>finishSession(document.getElementById(\"noteInput\").value.trim()));\n}\nasync function finishSession(note){\n  const end = new Date().toISOString();\n  const durationMs = new Date(end).getTime() - new Date(running.start).getTime();\n  sessions.push({ id: Date.now().toString(36)+Math.random().toString(36).slice(2,6), start: running.start, end, durationMs, note });\n  await storeSet(\"work-sessions:\"+todayKey(), sessions);\n  running = null;\n  await storeSet(\"work-running\", null);\n  document.getElementById(\"sheetLayer\").innerHTML = \"\";\n  stopTicking(); renderWork();\n  showToast(\"Session saved\");\n}\n\n/* ---------- ROUTINE TAB ---------- */\nlet routineState = {};\nasync function loadRoutine(){ routineState = (await storeGet(\"routine:\"+todayKey())) || {}; renderRoutine(); }\nfunction renderRoutine(){\n  const el = document.getElementById(\"routineTab\");\n  el.innerHTML = ROUTINE.map(sec => `\n    <div class=\"section-title\">${sec.section}</div>\n    ${sec.items.map(item => `\n      <div class=\"routine-item ${routineState[item.id] ? 'done':''}\" data-id=\"${item.id}\">\n        <div class=\"check ${routineState[item.id] ? 'checked':''}\"></div>\n        <div class=\"routine-text\"><div class=\"name\">${item.name}</div><div class=\"time\">${to12h(item.time)}</div></div>\n      </div>`).join(\"\")}\n  `).join(\"\");\n  el.querySelectorAll(\".routine-item\").forEach(row=>{\n    row.addEventListener(\"click\", async ()=>{\n      const id = row.dataset.id;\n      routineState[id] = !routineState[id];\n      await storeSet(\"routine:\"+todayKey(), routineState);\n      renderRoutine();\n    });\n  });\n}\nfunction to12h(t){\n  const [h,m] = t.split(\":\").map(Number);\n  const period = h>=12 ? \"PM\" : \"AM\";\n  const hh = h%12 === 0 ? 12 : h%12;\n  return hh+\":\"+String(m).padStart(2,\"0\")+\" \"+period;\n}\n\n/* ---------- SALES + STOCK (shared inventory) ---------- */\nlet products = [];     // {id, name, unit, salePrice, stock}\nlet purchases = [];    // {id, productId, qty, price, date}\nlet cart = [];\nlet salesToday = [];\nlet currentPhotoBillId = null;\n\n// Khata (customer credit ledger) + Suppliers + Cash Book\nlet customers = [];   // {id, name, phone}\nlet khataTx = [];     // {id, customerId, type:'credit'|'payment', amount, note, date, billId?}\nlet suppliers = [];   // {id, name, phone}\nlet supplierTx = [];  // {id, supplierId, type:'credit'|'payment', amount, note, date}\nlet cashbook = [];    // {id, type:'in'|'out', amount, note, date}\nlet ledgerView = \"khata\";\n\nasync function loadInventory(){\n  products = (await storeGet(\"pos-products\")) || [];\n  purchases = (await storeGet(\"purchases\")) || [];\n  cart = (await storeGet(\"pos-cart\")) || [];\n  salesToday = (await storeGet(\"pos-sales:\"+todayKey())) || [];\n  renderPOS();\n  renderStock();\n}\nasync function loadLedger(){\n  customers = (await storeGet(\"khata-customers\")) || [];\n  khataTx = (await storeGet(\"khata-tx\")) || [];\n  suppliers = (await storeGet(\"khata-suppliers\")) || [];\n  supplierTx = (await storeGet(\"supplier-tx\")) || [];\n  cashbook = (await storeGet(\"cashbook\")) || [];\n  renderLedger();\n}\nfunction customerBalance(customerId){\n  return khataTx.filter(t=>t.customerId===customerId).reduce((s,t)=> s + (t.type===\"credit\" ? t.amount : -t.amount), 0);\n}\nfunction supplierBalance(supplierId){\n  return supplierTx.filter(t=>t.supplierId===supplierId).reduce((s,t)=> s + (t.type===\"credit\" ? t.amount : -t.amount), 0);\n}\nfunction cashInHand(){\n  return cashbook.reduce((s,e)=> s + (e.type===\"in\" ? e.amount : -e.amount), 0);\n}\nfunction waLink(phone, text){\n  const digits = (phone||\"\").replace(/[^0-9]/g, \"\");\n  return \"https://wa.me/\" + digits + \"?text=\" + encodeURIComponent(text);\n}\nfunction avgCost(productId){\n  const rel = purchases.filter(p=>p.productId===productId);\n  if(rel.length===0) return null;\n  const totalQty = rel.reduce((s,p)=>s+p.qty,0);\n  const totalCost = rel.reduce((s,p)=>s+p.qty*p.price,0);\n  return totalQty>0 ? totalCost/totalQty : null;\n}\n\n/* --- Sales tab (overview) --- */\nfunction renderPOS(){\n  const el = document.getElementById(\"salesTab\");\n  const totalRevenue = salesToday.reduce((s,b)=>s+b.total,0);\n  const profitToday = salesToday.reduce((s,b)=> s + b.items.reduce((ss,i)=> ss + (i.price - (avgCost(i.productId)||0))*i.qty, 0), 0);\n\n  el.innerHTML = `\n    <div class=\"card\">\n      <div class=\"section-title\" style=\"margin-top:0;\">Products &amp; stock</div>\n      <div id=\"productList\"></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"today-total\"><span class=\"label\">Sold today</span><span class=\"value\">Rs ${totalRevenue.toFixed(0)}</span></div>\n      <div class=\"today-total\" style=\"margin-top:6px;\"><span class=\"label\">Bills today</span><span class=\"value\">${salesToday.length}</span></div>\n      <div class=\"today-total\" style=\"margin-top:6px;\"><span class=\"label\">Profit today</span><span class=\"value\">Rs ${profitToday.toFixed(0)}</span></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"section-title\" style=\"margin-top:0;\">Today's bills</div>\n      <div id=\"billsList\"></div>\n    </div>\n    <div class=\"fab-wrap\"><div class=\"fab-inner\"><button class=\"fab\" id=\"newBillFab\">+</button></div></div>\n  `;\n\n  const productList = document.getElementById(\"productList\");\n  if(products.length === 0){\n    productList.innerHTML = '<div class=\"empty-note\">No products yet — add one from the Stock tab</div>';\n  } else {\n    productList.innerHTML = products.map(p => `\n      <div class=\"product-row\">\n        <div>\n          <div class=\"pname\">${escapeHtml(p.name)}</div>\n          <div class=\"psub\">Rs ${p.salePrice} / ${escapeHtml(p.unit || 'pcs')}</div>\n        </div>\n        <div class=\"pqty\">\n          ${formatQty(p.stock, p.unit)}\n          ${p.stock <= 5 ? '<div class=\"tag-low\" style=\"margin-top:3px;display:inline-block;\">Low</div>' : ''}\n        </div>\n      </div>`).join(\"\");\n  }\n\n  const billsList = document.getElementById(\"billsList\");\n  if(salesToday.length === 0){\n    billsList.innerHTML = '<div class=\"empty-note\">No sales yet today</div>';\n  } else {\n    billsList.innerHTML = salesToday.slice().reverse().map(b => `\n      <div class=\"bill-card\">\n        <div class=\"bill-head\"><span>${fmtTimeLabel(b.time)}</span><span class=\"dur\">Rs ${b.total.toFixed(0)}</span></div>\n        <div class=\"bill-items\">${b.items.map(i=>`${formatQty(i.qty, i.unit)} ${escapeHtml(i.name)}`).join(\", \")}</div>\n        ${b.creditAmount ? `<span class=\"pay-badge ${b.paidCash>0?'partial':'credit'}\">${b.paidCash>0 ? 'Partial · Rs '+b.creditAmount.toFixed(0)+' credit' : 'On credit'}${b.customerName ? ' — '+escapeHtml(b.customerName) : ''}</span>` : `<span class=\"pay-badge cash\">Cash</span>`}\n        <div class=\"bill-actions\">\n          <button class=\"icon-btn\" data-act=\"photo\" data-id=\"${b.id}\" title=\"Bill photo\">${b.hasPaperPhoto?'🖼️':'📷'}</button>\n          <button class=\"icon-btn\" data-act=\"receipt\" data-id=\"${b.id}\" title=\"Receipt image\">🧾</button>\n        </div>\n      </div>`).join(\"\");\n    billsList.querySelectorAll('[data-act=\"photo\"]').forEach(btn=> btn.addEventListener(\"click\", ()=>openPhotoSheet(btn.dataset.id)));\n    billsList.querySelectorAll('[data-act=\"receipt\"]').forEach(btn=> btn.addEventListener(\"click\", ()=>{\n      const bill = salesToday.find(x=>x.id===btn.dataset.id);\n      if(bill) openReceiptSheet(bill);\n    }));\n  }\n\n  document.getElementById(\"newBillFab\").addEventListener(\"click\", openCreateBillSheet);\n}\n\n/* --- Create bill sheet (opened from the + button) --- */\nlet billPartyId = null;\nlet billPartyName = null;\nfunction openCreateBillSheet(){\n  billPartyId = null;\n  billPartyName = null;\n  const layer = document.getElementById(\"sheetLayer\");\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>New bill</h2>\n    <p>Who is this bill for?</p>\n    <select id=\"billPartySelect\" class=\"select-field\">\n      <option value=\"\">Walk-in / cash customer</option>\n      <option value=\"__new__\">+ New customer</option>\n      ${customerSelectOptions()}\n    </select>\n    <div id=\"billNewPartyFields\" style=\"display:none;\">\n      <span class=\"form-label\">Name</span>\n      <input type=\"text\" id=\"billNewPartyName\" placeholder=\"Customer name\">\n      <span class=\"form-label\">Phone (optional)</span>\n      <input type=\"text\" id=\"billNewPartyPhone\" placeholder=\"e.g. 03001234567\">\n    </div>\n    <div class=\"sheet-actions\">\n      <button class=\"btn-skip\" id=\"cancelBillParty\">Cancel</button>\n      <button class=\"btn-save\" id=\"continueBillParty\">Continue</button>\n    </div>\n  </div></div>`;\n  const sel = document.getElementById(\"billPartySelect\");\n  sel.addEventListener(\"change\", ()=>{\n    document.getElementById(\"billNewPartyFields\").style.display = sel.value === \"__new__\" ? \"block\" : \"none\";\n  });\n  document.getElementById(\"cancelBillParty\").addEventListener(\"click\", ()=> layer.innerHTML=\"\");\n  document.getElementById(\"continueBillParty\").addEventListener(\"click\", async ()=>{\n    if(sel.value === \"__new__\"){\n      const name = document.getElementById(\"billNewPartyName\").value.trim();\n      if(!name){ showToast(\"Enter customer name\"); return; }\n      const phone = document.getElementById(\"billNewPartyPhone\").value.trim();\n      const newCust = {id: Date.now().toString(36), name, phone};\n      customers.push(newCust);\n      await storeSet(\"khata-customers\", customers);\n      billPartyId = newCust.id; billPartyName = newCust.name;\n    } else if(sel.value){\n      const c = customers.find(x=>x.id===sel.value);\n      billPartyId = c.id; billPartyName = c.name;\n    }\n    renderBillPickItemsStep();\n  });\n}\nfunction renderBillPickItemsStep(){\n  const layer = document.getElementById(\"sheetLayer\");\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>${billPartyName ? escapeHtml(billPartyName) : \"Walk-in sale\"}</h2>\n    <div class=\"cart-total-row\" style=\"margin-bottom:14px;\"><span>Total</span><span id=\"runningTotalVal\">Rs 0</span></div>\n    <div class=\"product-grid\" id=\"billProductGrid\"></div>\n    <div id=\"billCartWrap\" style=\"margin-top:14px;\"></div>\n  </div></div>`;\n  renderBillSheet();\n}\nfunction renderBillSheet(){\n  const grid = document.getElementById(\"billProductGrid\");\n  if(!grid) return;\n  if(products.length === 0){\n    grid.innerHTML = '<div class=\"empty-note\" style=\"grid-column:1/-1;\">No products yet — add one from the Stock tab first</div>';\n  } else {\n    grid.innerHTML = products.map(p=>{\n      const inCart = cart.find(i=>i.productId===p.id);\n      const remaining = p.stock - (inCart?inCart.qty:0);\n      const out = remaining<=0;\n      return `<button class=\"product-btn\" data-id=\"${p.id}\" ${out?'disabled style=\"opacity:0.45;\"':''}>\n        <div class=\"pname\">${escapeHtml(p.name)}</div>\n        <div class=\"pprice\">Rs ${p.salePrice}/${escapeHtml(p.unit||'pcs')}</div>\n        <div class=\"pprice\">${out?'Out of stock':formatQty(remaining,p.unit)+' left'}</div>\n      </button>`;\n    }).join(\"\");\n    grid.querySelectorAll(\".product-btn:not(:disabled)\").forEach(btn=>{\n      btn.addEventListener(\"click\", ()=>{ addToCart(btn.dataset.id); renderBillSheet(); });\n    });\n  }\n  const wrap = document.getElementById(\"billCartWrap\");\n  const cartTotal = cart.reduce((s,i)=>s+i.price*i.qty,0);\n  const totalVal = document.getElementById(\"runningTotalVal\");\n  if(totalVal) totalVal.textContent = \"Rs \" + cartTotal.toFixed(0);\n  wrap.innerHTML = `\n    ${cart.length===0 ? '<div class=\"empty-note\">No items added yet</div>' : '<div id=\"billCartList\"></div>'}\n    <div class=\"sheet-actions\" style=\"margin-top:14px;\">\n      <button class=\"btn-skip\" id=\"cancelBill\">Cancel</button>\n      ${cart.length>0 ? '<button class=\"btn-save\" id=\"completeBillBtn\">Complete sale</button>' : ''}\n    </div>`;\n  if(cart.length>0){\n    document.getElementById(\"billCartList\").innerHTML = cart.map(i=>`\n      <div class=\"cart-row\">\n        <div>${escapeHtml(i.name)} <span style=\"color:var(--ink-soft); font-size:13px;\">Rs ${i.price}/${escapeHtml(i.unit||'pcs')}</span></div>\n        <div class=\"qty-controls\">\n          <button class=\"qty-btn\" data-id=\"${i.productId}\" data-act=\"dec\">−</button>\n          <span>${formatQty(i.qty, i.unit)}</span>\n          <button class=\"qty-btn\" data-id=\"${i.productId}\" data-act=\"inc\">+</button>\n        </div>\n      </div>`).join(\"\");\n    document.querySelectorAll(\"#billCartList .qty-btn\").forEach(btn=>{\n      btn.addEventListener(\"click\", ()=>{ changeQty(btn.dataset.id, btn.dataset.act); renderBillSheet(); });\n    });\n    document.getElementById(\"completeBillBtn\").addEventListener(\"click\", ()=> openBillPaymentStep(cartTotal));\n  }\n  document.getElementById(\"cancelBill\").addEventListener(\"click\", ()=>{ document.getElementById(\"sheetLayer\").innerHTML = \"\"; });\n}\nfunction openBillPaymentStep(total){\n  const layer = document.getElementById(\"sheetLayer\");\n  const partyLine = billPartyId ? `<p>Adding to <strong>${escapeHtml(billPartyName)}</strong>'s account if not paid in full.</p>` : \"\";\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>Payment</h2>\n    <p>Total due: Rs ${total.toFixed(0)}</p>\n    ${partyLine}\n    <div class=\"subtab-row\">\n      <button type=\"button\" class=\"subtab-btn active\" id=\"payCash\">Full cash</button>\n      <button type=\"button\" class=\"subtab-btn\" id=\"payCredit\">Full credit</button>\n      <button type=\"button\" class=\"subtab-btn\" id=\"payPartial\">Partial</button>\n    </div>\n    <div id=\"paymentFields\"></div>\n    <div class=\"sheet-actions\" style=\"margin-top:6px;\">\n      <button class=\"btn-skip\" id=\"backToBill\">Back</button>\n      <button class=\"btn-save\" id=\"confirmPayment\">Complete sale</button>\n    </div>\n  </div></div>`;\n  let payMode = \"cash\";\n  const fieldsEl = document.getElementById(\"paymentFields\");\n  function customerPickerHtml(){\n    if(billPartyId){\n      return `<p style=\"margin-top:0;\">This will be added to <strong>${escapeHtml(billPartyName)}</strong>'s balance.</p>`;\n    }\n    return `\n      <span class=\"form-label\">Customer</span>\n      <select id=\"payCustomer\" class=\"select-field\">\n        <option value=\"__new__\">+ New customer</option>\n        ${customerSelectOptions()}\n      </select>\n      <div id=\"payNewCustFields\" style=\"display:${customers.length===0?'block':'none'};\">\n        <span class=\"form-label\">Name</span>\n        <input type=\"text\" id=\"payNewName\" placeholder=\"Customer name\">\n        <span class=\"form-label\">Phone (optional)</span>\n        <input type=\"text\" id=\"payNewPhone\" placeholder=\"e.g. 03001234567\">\n      </div>`;\n  }\n  function renderFields(){\n    if(payMode === \"cash\"){\n      fieldsEl.innerHTML = `<p style=\"margin-top:0;\">Full amount is paid now in cash.</p>`;\n    } else if(payMode === \"credit\"){\n      fieldsEl.innerHTML = customerPickerHtml();\n      if(!billPartyId) wireNewCustomerFields(document.getElementById(\"payCustomer\"), \"payNewCustFields\");\n    } else {\n      fieldsEl.innerHTML = `\n        <span class=\"form-label\">Amount received now (cash)</span>\n        <input type=\"number\" id=\"payCashNow\" placeholder=\"e.g. ${Math.round(total/2)}\">\n        ${customerPickerHtml()}`;\n      if(!billPartyId) wireNewCustomerFields(document.getElementById(\"payCustomer\"), \"payNewCustFields\");\n    }\n  }\n  renderFields();\n  function selectMode(mode, btn){\n    payMode = mode;\n    [payCashBtn, payCreditBtn, payPartialBtn].forEach(b=>b.classList.remove(\"active\"));\n    btn.classList.add(\"active\");\n    renderFields();\n  }\n  const payCashBtn = document.getElementById(\"payCash\");\n  const payCreditBtn = document.getElementById(\"payCredit\");\n  const payPartialBtn = document.getElementById(\"payPartial\");\n  payCashBtn.addEventListener(\"click\", ()=> selectMode(\"cash\", payCashBtn));\n  payCreditBtn.addEventListener(\"click\", ()=> selectMode(\"credit\", payCreditBtn));\n  payPartialBtn.addEventListener(\"click\", ()=> selectMode(\"partial\", payPartialBtn));\n\n  document.getElementById(\"backToBill\").addEventListener(\"click\", ()=>{ renderBillPickItemsStep(); });\n  document.getElementById(\"confirmPayment\").addEventListener(\"click\", async ()=>{\n    let paidCash = total, creditAmount = 0, customerId = billPartyId;\n    if(payMode === \"credit\" || payMode === \"partial\"){\n      if(payMode === \"partial\"){\n        const entered = parseFloat(document.getElementById(\"payCashNow\").value);\n        paidCash = isNaN(entered) ? 0 : Math.min(Math.max(entered,0), total);\n        creditAmount = Math.round((total - paidCash)*100)/100;\n      } else {\n        paidCash = 0; creditAmount = total;\n      }\n      if(!billPartyId){\n        const sel = document.getElementById(\"payCustomer\");\n        customerId = sel.value;\n        if(customerId === \"__new__\"){\n          const name = document.getElementById(\"payNewName\").value.trim();\n          if(!name){ showToast(\"Enter customer name\"); return; }\n          const phone = document.getElementById(\"payNewPhone\").value.trim();\n          const newCust = {id: Date.now().toString(36), name, phone};\n          customers.push(newCust);\n          await storeSet(\"khata-customers\", customers);\n          customerId = newCust.id;\n        }\n      }\n    }\n    await completeSale({paidCash, creditAmount, customerId});\n    document.getElementById(\"sheetLayer\").innerHTML = \"\";\n  });\n}\nfunction addToCart(productId){\n  const p = products.find(x=>x.id===productId);\n  if(!p) return;\n  const existing = cart.find(i=>i.productId===productId);\n  const currentQty = existing?existing.qty:0;\n  if(currentQty >= p.stock){ showToast(\"Out of stock\"); return; }\n  if(existing) existing.qty += 1;\n  else cart.push({productId:p.id, name:p.name, price:p.salePrice, unit:p.unit||'pcs', qty:1});\n  storeSet(\"pos-cart\", cart);\n}\nfunction changeQty(productId, act){\n  const item = cart.find(i=>i.productId===productId);\n  if(!item) return;\n  const prod = products.find(p=>p.id===productId);\n  const step = unitStep(item.unit);\n  if(act === \"inc\"){\n    if(prod && item.qty + step > prod.stock + 0.0001){ showToast(\"Out of stock\"); return; }\n    item.qty = Math.round((item.qty + step) * 100) / 100;\n  } else {\n    item.qty = Math.round((item.qty - step) * 100) / 100;\n  }\n  if(item.qty <= 0) cart = cart.filter(i=>i.productId!==productId);\n  storeSet(\"pos-cart\", cart);\n}\nasync function completeSale(payment){\n  const total = cart.reduce((s,i)=>s+i.price*i.qty,0);\n  const paidCash = payment ? payment.paidCash : total;\n  const creditAmount = payment ? payment.creditAmount : 0;\n  const customerId = payment ? payment.customerId : null;\n  const customer = customerId ? customers.find(c=>c.id===customerId) : null;\n  const bill = {\n    id: Date.now().toString(36), time: new Date().toISOString(),\n    items: cart.map(i=>({...i})), total, hasPaperPhoto:false,\n    paidCash, creditAmount, customerId, customerName: customer ? customer.name : null\n  };\n  cart.forEach(i=>{\n    const prod = products.find(p=>p.id===i.productId);\n    if(prod) prod.stock = Math.max(0, Math.round((prod.stock - i.qty)*100)/100);\n  });\n  await storeSet(\"pos-products\", products);\n  salesToday.push(bill);\n  await storeSet(\"pos-sales:\"+todayKey(), salesToday);\n  cart = [];\n  await storeSet(\"pos-cart\", cart);\n\n  if(paidCash > 0){\n    cashbook.push({id: Date.now().toString(36)+\"c\", type:\"in\", amount: paidCash, note:\"Sale\", date: bill.time, partyType: customer?\"customer\":null, partyId: customer?customer.id:null, partyName: customer?customer.name:null});\n    await storeSet(\"cashbook\", cashbook);\n  }\n  if(creditAmount > 0 && customerId){\n    khataTx.push({id: Date.now().toString(36)+\"k\", customerId, type:\"credit\", amount: creditAmount, note: \"Bill \"+bill.id, date: bill.time, billId: bill.id});\n    await storeSet(\"khata-tx\", khataTx);\n  }\n\n  renderPOS(); renderStock(); renderLedger();\n  showToast(\"Sale recorded\");\n}\n\n/* --- Bill photo (paper receipt) --- */\nasync function openPhotoSheet(billId){\n  const layer = document.getElementById(\"sheetLayer\");\n  const existing = await storeGet(\"bill-photo:\"+billId);\n  if(existing){\n    layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n      <h2>Bill photo</h2>\n      <img src=\"${existing}\" class=\"receipt-preview\">\n      <div class=\"sheet-actions\">\n        <button class=\"btn-skip\" id=\"closePhoto\">Close</button>\n        <button class=\"btn-save\" id=\"retakePhoto\">Retake</button>\n      </div></div></div>`;\n    document.getElementById(\"closePhoto\").addEventListener(\"click\", ()=>layer.innerHTML=\"\");\n    document.getElementById(\"retakePhoto\").addEventListener(\"click\", ()=>{ layer.innerHTML=\"\"; triggerPhotoCapture(billId); });\n  } else {\n    triggerPhotoCapture(billId);\n  }\n}\nfunction triggerPhotoCapture(billId){\n  currentPhotoBillId = billId;\n  document.getElementById(\"photoInput\").click();\n}\nfunction compressImage(file){\n  return new Promise((resolve, reject)=>{\n    const reader = new FileReader();\n    reader.onload = e => {\n      const img = new Image();\n      img.onload = () => {\n        const maxW = 800;\n        const scale = Math.min(1, maxW/img.width);\n        const canvas = document.createElement(\"canvas\");\n        canvas.width = Math.round(img.width*scale);\n        canvas.height = Math.round(img.height*scale);\n        const ctx = canvas.getContext(\"2d\");\n        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);\n        resolve(canvas.toDataURL(\"image/jpeg\", 0.6));\n      };\n      img.onerror = reject;\n      img.src = e.target.result;\n    };\n    reader.onerror = reject;\n    reader.readAsDataURL(file);\n  });\n}\ndocument.getElementById(\"photoInput\").addEventListener(\"change\", async (e)=>{\n  const file = e.target.files[0];\n  if(!file || !currentPhotoBillId) return;\n  try{\n    const dataUrl = await compressImage(file);\n    await storeSet(\"bill-photo:\"+currentPhotoBillId, dataUrl);\n    const bill = salesToday.find(b=>b.id===currentPhotoBillId);\n    if(bill){ bill.hasPaperPhoto = true; await storeSet(\"pos-sales:\"+todayKey(), salesToday); }\n    showToast(\"Photo attached\");\n    renderPOS();\n  }catch(err){ showToast(\"Couldn't process photo\"); }\n  e.target.value = \"\";\n});\n\n/* --- Auto-generated receipt image --- */\nfunction generateReceiptDataUrl(bill){\n  const width = 380;\n  const lineHeight = 22;\n  const height = 150 + bill.items.length*lineHeight + 50;\n  const canvas = document.createElement(\"canvas\");\n  canvas.width = width; canvas.height = height;\n  const ctx = canvas.getContext(\"2d\");\n  ctx.fillStyle = \"#FBF9F4\"; ctx.fillRect(0,0,width,height);\n  ctx.fillStyle = \"#1C2E20\";\n  ctx.font = \"600 20px Georgia, serif\";\n  ctx.textAlign = \"center\";\n  ctx.fillText(\"Receipt\", width/2, 34);\n  ctx.font = \"13px Arial\";\n  ctx.fillStyle = \"#5B6156\";\n  ctx.fillText(new Date(bill.time).toLocaleString(), width/2, 54);\n  ctx.strokeStyle = \"#DCD6C7\";\n  ctx.beginPath(); ctx.moveTo(20,68); ctx.lineTo(width-20,68); ctx.stroke();\n  let y = 92;\n  ctx.font = \"14px Arial\";\n  bill.items.forEach(i=>{\n    ctx.textAlign = \"left\"; ctx.fillStyle = \"#22271F\";\n    ctx.fillText(`${formatQty(i.qty,i.unit)} × ${i.name}`, 20, y);\n    ctx.textAlign = \"right\";\n    ctx.fillText(\"Rs \" + (i.price*i.qty).toFixed(0), width-20, y);\n    y += lineHeight;\n  });\n  y += 6;\n  ctx.beginPath(); ctx.moveTo(20,y); ctx.lineTo(width-20,y); ctx.stroke();\n  y += 28;\n  ctx.font = \"600 17px Arial\";\n  ctx.textAlign = \"left\"; ctx.fillText(\"Total\", 20, y);\n  ctx.textAlign = \"right\"; ctx.fillText(\"Rs \" + bill.total.toFixed(0), width-20, y);\n  return canvas.toDataURL(\"image/png\");\n}\nfunction openReceiptSheet(bill){\n  const layer = document.getElementById(\"sheetLayer\");\n  const dataUrl = generateReceiptDataUrl(bill);\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>Receipt</h2>\n    <img src=\"${dataUrl}\" class=\"receipt-preview\">\n    <div class=\"sheet-actions\">\n      <button class=\"btn-skip\" id=\"closeReceipt\">Close</button>\n      <button class=\"btn-save\" id=\"downloadReceipt\">${navigator.share ? 'Share' : 'Download'}</button>\n    </div></div></div>`;\n  document.getElementById(\"closeReceipt\").addEventListener(\"click\", ()=>layer.innerHTML=\"\");\n  document.getElementById(\"downloadReceipt\").addEventListener(\"click\", async ()=>{\n    if(navigator.share){\n      try{\n        const blob = await (await fetch(dataUrl)).blob();\n        const file = new File([blob], \"receipt.png\", {type:\"image/png\"});\n        if(navigator.canShare && navigator.canShare({files:[file]})){\n          await navigator.share({files:[file], title:\"Receipt\"});\n          return;\n        }\n      }catch(e){}\n    }\n    const a = document.createElement(\"a\");\n    a.href = dataUrl; a.download = \"receipt-\"+bill.id+\".png\"; a.click();\n  });\n}\n\n/* --- Stock tab --- */\nfunction renderStock(){\n  const el = document.getElementById(\"stockTab\");\n  el.innerHTML = `\n    <div class=\"card\">\n      <div style=\"display:flex; justify-content:space-between; align-items:center;\">\n        <div class=\"section-title\" style=\"margin:0;\">Inventory</div>\n        <button class=\"gear-btn\" style=\"font-size:13px; text-decoration:underline;\" id=\"importProductsBtn\">⬆ Import list</button>\n      </div>\n      <button class=\"btn-complete\" id=\"restockBtn\">+ Restock / add product</button>\n    </div>\n    <div class=\"card\">\n      <div style=\"display:flex; justify-content:space-between; align-items:center;\">\n        <div class=\"section-title\" style=\"margin:0;\">Stock on hand</div>\n        <button class=\"gear-btn\" id=\"manageProductsBtn\">⚙</button>\n      </div>\n      <div id=\"stockList\" style=\"margin-top:6px;\"></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"section-title\" style=\"margin-top:0;\">Recent purchases</div>\n      <div id=\"purchaseLog\"></div>\n    </div>\n  `;\n  const stockList = document.getElementById(\"stockList\");\n  if(products.length===0){\n    stockList.innerHTML = '<div class=\"empty-note\">No products yet — tap \"+ Restock\" to add one</div>';\n  } else {\n    stockList.innerHTML = products.map(p=>{\n      const cost = avgCost(p.id);\n      const value = (cost||0)*p.stock;\n      return `<div class=\"stock-card\">\n        <div class=\"stock-head\">\n          <span class=\"pname\">${escapeHtml(p.name)}${p.stock<=5?'<span class=\"tag-low\">Low stock</span>':''}</span>\n          <span class=\"qty\">${formatQty(p.stock, p.unit)}</span>\n        </div>\n        <div class=\"stock-sub\">\n          <span>Sale Rs ${p.salePrice}/${escapeHtml(p.unit||'pcs')}</span>\n          <span>${cost!==null ? 'Avg cost Rs '+cost.toFixed(1) : 'No purchases yet'}</span>\n          ${cost!==null ? `<span>Value Rs ${value.toFixed(0)}</span>` : ''}\n        </div>\n      </div>`;\n    }).join(\"\");\n  }\n  const log = document.getElementById(\"purchaseLog\");\n  const recent = purchases.slice().sort((a,b)=> new Date(b.date)-new Date(a.date)).slice(0,15);\n  if(recent.length===0){\n    log.innerHTML = '<div class=\"empty-note\">No purchases logged yet</div>';\n  } else {\n    log.innerHTML = recent.map(pu=>{\n      const prod = products.find(x=>x.id===pu.productId);\n      return `<div class=\"purchase-log-row\"><span>${formatQty(pu.qty, prod?prod.unit:'')} × ${escapeHtml(prod?prod.name:'Unknown')} @ Rs ${pu.price}${pu.ref ? ' · '+escapeHtml(pu.ref) : ''}</span><span>${new Date(pu.date).toLocaleDateString()}</span></div>`;\n    }).join(\"\");\n  }\n  document.getElementById(\"restockBtn\").addEventListener(\"click\", openRestockSheet);\n  document.getElementById(\"manageProductsBtn\").addEventListener(\"click\", openManageProductsSheet);\n  document.getElementById(\"importProductsBtn\").addEventListener(\"click\", openProductImportSheet);\n}\nfunction openRestockSheet(){\n  const layer = document.getElementById(\"sheetLayer\");\n  const options = products.map(p=>`<option value=\"${p.id}\">${escapeHtml(p.name)}</option>`).join(\"\");\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>Restock</h2>\n    <p>Log a purchase batch — this adds to stock automatically.</p>\n    <span class=\"form-label\">Product</span>\n    <select id=\"restockProduct\" class=\"select-field\">\n      <option value=\"__new__\">+ New product</option>\n      ${options}\n    </select>\n    <div id=\"newProductFields\" style=\"display:none;\">\n      <span class=\"form-label\">Product name</span>\n      <input type=\"text\" id=\"newProdName\" placeholder=\"e.g. 115 No. Bracket\">\n      <span class=\"form-label\">Unit</span>\n      <select id=\"newProdUnit\" class=\"select-field\">\n        <option value=\"pcs\">Piece (pcs)</option>\n        <option value=\"kg\">Kilogram (kg)</option>\n        <option value=\"g\">Gram (g)</option>\n        <option value=\"litre\">Litre</option>\n        <option value=\"dozen\">Dozen</option>\n        <option value=\"box\">Box</option>\n        <option value=\"custom\">Custom...</option>\n      </select>\n      <input type=\"text\" id=\"newProdUnitCustom\" placeholder=\"Unit name (e.g. bag, roll)\" style=\"display:none;\">\n      <span class=\"form-label\">Sale price (per unit)</span>\n      <input type=\"number\" id=\"newProdSalePrice\" placeholder=\"e.g. 65\">\n    </div>\n    <span class=\"form-label\">Quantity purchased <span id=\"qtyUnitHint\"></span></span>\n    <input type=\"number\" step=\"0.01\" id=\"restockQty\" placeholder=\"e.g. 4000\">\n    <span class=\"form-label\">Price entry</span>\n    <div style=\"display:flex; gap:8px; margin-bottom:12px;\">\n      <button type=\"button\" class=\"toggle-btn active\" id=\"priceModeUnit\">Per unit</button>\n      <button type=\"button\" class=\"toggle-btn\" id=\"priceModeTotal\">Total paid</button>\n    </div>\n    <span class=\"form-label\" id=\"priceFieldLabel\">Purchase price (per unit)</span>\n    ${calcFieldHtml(\"restockPrice\", \"e.g. 53\")}\n    <span class=\"form-label\">Bill / reference no. (optional)</span>\n    <input type=\"text\" id=\"restockBillNo\" placeholder=\"e.g. INV-2201\">\n\n    <div class=\"cart-total-row\" style=\"margin:4px 0 12px;\"><span>Batch total</span><span id=\"restockBatchTotal\">Rs 0</span></div>\n    <span class=\"form-label\">Payment to supplier</span>\n    <div class=\"subtab-row\">\n      <button type=\"button\" class=\"subtab-btn active\" id=\"rsPayCash\">Paid cash</button>\n      <button type=\"button\" class=\"subtab-btn\" id=\"rsPayCredit\">On credit</button>\n      <button type=\"button\" class=\"subtab-btn\" id=\"rsPayPartial\">Partial</button>\n    </div>\n    <div id=\"rsSupplierWrap\" style=\"display:none;\">\n      <span class=\"form-label\">Supplier</span>\n      <select id=\"rsSupplier\" class=\"select-field\">\n        ${suppliers.map(s=>`<option value=\"${s.id}\">${escapeHtml(s.name)}</option>`).join(\"\")}\n        <option value=\"__new__\">+ New supplier</option>\n      </select>\n      <div id=\"rsNewSupWrap\" style=\"display:${suppliers.length===0?'block':'none'};\">\n        <span class=\"form-label\">Name</span>\n        <input type=\"text\" id=\"rsNewSupName\" placeholder=\"Supplier name\">\n        <span class=\"form-label\">Phone (optional)</span>\n        <input type=\"text\" id=\"rsNewSupPhone\" placeholder=\"e.g. 03001234567\">\n      </div>\n    </div>\n    <div id=\"rsPartialWrap\" style=\"display:none;\">\n      <span class=\"form-label\">Amount paid now (cash)</span>\n      <input type=\"number\" id=\"rsCashNow\" placeholder=\"e.g. 2500\">\n    </div>\n\n    <div class=\"sheet-actions\" style=\"margin-top:6px;\">\n      <button class=\"btn-skip\" id=\"cancelRestock\">Cancel</button>\n      <button class=\"btn-save\" id=\"saveRestock\">Add to stock</button>\n    </div></div></div>`;\n  const sel = document.getElementById(\"restockProduct\");\n  const newFields = document.getElementById(\"newProductFields\");\n  const unitSel = document.getElementById(\"newProdUnit\");\n  const unitCustom = document.getElementById(\"newProdUnitCustom\");\n\n  function updateHint(){\n    const hint = document.getElementById(\"qtyUnitHint\");\n    if(sel.value === \"__new__\"){\n      const u = unitSel.value === \"custom\" ? (unitCustom.value.trim() || \"unit\") : unitSel.value;\n      hint.textContent = \"(in \" + (UNIT_LABELS[u] || u) + \")\";\n    } else {\n      const prod = products.find(p=>p.id===sel.value);\n      const u = prod ? (prod.unit || \"pcs\") : \"pcs\";\n      hint.textContent = \"(in \" + (UNIT_LABELS[u] || u) + \")\";\n    }\n  }\n  sel.addEventListener(\"change\", ()=>{\n    newFields.style.display = sel.value === \"__new__\" ? \"block\" : \"none\";\n    updateHint();\n  });\n  unitSel.addEventListener(\"change\", ()=>{\n    unitCustom.style.display = unitSel.value === \"custom\" ? \"block\" : \"none\";\n    updateHint();\n  });\n  unitCustom.addEventListener(\"input\", updateHint);\n  newFields.style.display = sel.value === \"__new__\" ? \"block\" : \"none\";\n  updateHint();\n\n  let priceMode = \"unit\";\n  const modeUnitBtn = document.getElementById(\"priceModeUnit\");\n  const modeTotalBtn = document.getElementById(\"priceModeTotal\");\n  const priceFieldLabel = document.getElementById(\"priceFieldLabel\");\n  const priceInput = document.getElementById(\"restockPrice\");\n  function setPriceMode(mode){\n    priceMode = mode;\n    modeUnitBtn.classList.toggle(\"active\", mode === \"unit\");\n    modeTotalBtn.classList.toggle(\"active\", mode === \"total\");\n    priceFieldLabel.textContent = mode === \"unit\" ? \"Purchase price (per unit)\" : \"Total amount paid (for this batch)\";\n    priceInput.placeholder = mode === \"unit\" ? \"e.g. 53\" : \"e.g. 5300\";\n  }\n  modeUnitBtn.addEventListener(\"click\", ()=>{ setPriceMode(\"unit\"); updateBatchTotal(); });\n  modeTotalBtn.addEventListener(\"click\", ()=>{ setPriceMode(\"total\"); updateBatchTotal(); });\n\n  // --- Payment to supplier (Cash / Credit / Partial) ---\n  let payMode = \"cash\";\n  const rsCashBtn = document.getElementById(\"rsPayCash\");\n  const rsCreditBtn = document.getElementById(\"rsPayCredit\");\n  const rsPartialBtn = document.getElementById(\"rsPayPartial\");\n  const rsSupplierWrap = document.getElementById(\"rsSupplierWrap\");\n  const rsPartialWrap = document.getElementById(\"rsPartialWrap\");\n  const rsSupplierSel = document.getElementById(\"rsSupplier\");\n  wireNewCustomerFields(rsSupplierSel, \"rsNewSupWrap\");\n  function setPayMode(mode){\n    payMode = mode;\n    [rsCashBtn, rsCreditBtn, rsPartialBtn].forEach(b=>b.classList.remove(\"active\"));\n    ({cash:rsCashBtn, credit:rsCreditBtn, partial:rsPartialBtn})[mode].classList.add(\"active\");\n    rsSupplierWrap.style.display = mode === \"cash\" ? \"none\" : \"block\";\n    rsPartialWrap.style.display = mode === \"partial\" ? \"block\" : \"none\";\n  }\n  rsCashBtn.addEventListener(\"click\", ()=>setPayMode(\"cash\"));\n  rsCreditBtn.addEventListener(\"click\", ()=>setPayMode(\"credit\"));\n  rsPartialBtn.addEventListener(\"click\", ()=>setPayMode(\"partial\"));\n\n  function currentBatchTotal(){\n    const q = parseFloat(document.getElementById(\"restockQty\").value);\n    const ep = parseFloat(document.getElementById(\"restockPrice\").value);\n    if(isNaN(q) || q<=0 || isNaN(ep) || ep<0) return 0;\n    const unitPrice = priceMode === \"total\" ? ep / q : ep;\n    return Math.round(q * unitPrice * 100) / 100;\n  }\n  function updateBatchTotal(){\n    document.getElementById(\"restockBatchTotal\").textContent = \"Rs \" + currentBatchTotal().toFixed(0);\n  }\n  document.getElementById(\"restockQty\").addEventListener(\"input\", updateBatchTotal);\n  document.getElementById(\"restockPrice\").addEventListener(\"input\", updateBatchTotal);\n  const rpPad = document.getElementById(\"restockPrice_pad\");\n  if(rpPad) rpPad.addEventListener(\"click\", ()=> setTimeout(updateBatchTotal, 0));\n  updateBatchTotal();\n\n  document.getElementById(\"cancelRestock\").addEventListener(\"click\", ()=> layer.innerHTML=\"\");\n  document.getElementById(\"saveRestock\").addEventListener(\"click\", async ()=>{\n    const qty = parseFloat(document.getElementById(\"restockQty\").value);\n    const enteredPrice = parseFloat(document.getElementById(\"restockPrice\").value);\n    if(isNaN(qty) || qty<=0 || isNaN(enteredPrice) || enteredPrice<0){ showToast(\"Enter a valid quantity and price\"); return; }\n    const price = priceMode === \"total\" ? Math.round((enteredPrice / qty) * 100) / 100 : enteredPrice;\n    const batchTotal = Math.round(qty * price * 100) / 100;\n\n    // Resolve supplier when this isn't a straight cash purchase\n    let supplierId = null, supplierName = null;\n    if(payMode !== \"cash\"){\n      supplierId = rsSupplierSel.value;\n      if(supplierId === \"__new__\"){\n        const sName = document.getElementById(\"rsNewSupName\").value.trim();\n        if(!sName){ showToast(\"Enter supplier name\"); return; }\n        const newSup = {id: Date.now().toString(36), name: sName, phone: document.getElementById(\"rsNewSupPhone\").value.trim()};\n        suppliers.push(newSup);\n        await storeSet(\"khata-suppliers\", suppliers);\n        supplierId = newSup.id; supplierName = newSup.name;\n      } else {\n        const s = suppliers.find(x=>x.id===supplierId);\n        if(!s){ showToast(\"Pick a supplier\"); return; }\n        supplierName = s.name;\n      }\n    }\n\n    // Split batch total into cash-now vs credit\n    let cashPaid = batchTotal, creditAmount = 0;\n    if(payMode === \"credit\"){ cashPaid = 0; creditAmount = batchTotal; }\n    else if(payMode === \"partial\"){\n      const entered = parseFloat(document.getElementById(\"rsCashNow\").value);\n      cashPaid = isNaN(entered) ? 0 : Math.min(Math.max(entered, 0), batchTotal);\n      creditAmount = Math.round((batchTotal - cashPaid) * 100) / 100;\n    }\n\n    let productId = sel.value;\n    if(productId === \"__new__\"){\n      const name = document.getElementById(\"newProdName\").value.trim();\n      const salePrice = parseFloat(document.getElementById(\"newProdSalePrice\").value);\n      const unit = unitSel.value === \"custom\" ? (unitCustom.value.trim() || \"unit\") : unitSel.value;\n      if(!name || isNaN(salePrice)){ showToast(\"Enter product name and sale price\"); return; }\n      const newProd = {id: Date.now().toString(36), name, unit, salePrice, stock:0};\n      products.push(newProd);\n      productId = newProd.id;\n    }\n    const ref = document.getElementById(\"restockBillNo\").value.trim();\n    const nowIso = new Date().toISOString();\n    purchases.push({id: Date.now().toString(36)+Math.random().toString(36).slice(2,6), productId, qty, price, date: nowIso, ref});\n    const prod = products.find(p=>p.id===productId);\n    prod.stock = Math.round((prod.stock + qty)*100)/100;\n    await storeSet(\"pos-products\", products);\n    await storeSet(\"purchases\", purchases);\n\n    if(cashPaid > 0){\n      cashbook.push({id: Date.now().toString(36)+Math.random().toString(36).slice(2,6), type:\"out\", amount: cashPaid, note: \"Restock — \" + prod.name + (ref ? \" (\"+ref+\")\" : \"\"), date: nowIso, partyType: supplierId ? \"supplier\" : null, partyId: supplierId, partyName: supplierName});\n      await storeSet(\"cashbook\", cashbook);\n    }\n    if(creditAmount > 0 && supplierId){\n      supplierTx.push({id: Date.now().toString(36)+Math.random().toString(36).slice(2,6), supplierId, type:\"credit\", amount: creditAmount, note: formatQty(qty, prod.unit) + \" \" + prod.name, ref, date: nowIso});\n      await storeSet(\"supplier-tx\", supplierTx);\n    }\n\n    layer.innerHTML = \"\";\n    showToast(creditAmount > 0 ? \"Stock added · Rs \" + creditAmount.toFixed(0) + \" on credit\" : \"Stock updated\");\n    renderStock(); renderPOS(); renderLedger();\n  });\n}\nfunction openProductImportSheet(){\n  const layer = document.getElementById(\"sheetLayer\");\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>Import products</h2>\n    <p>One per line: <strong>Name, Unit, Sale price, Stock qty</strong>. Unit and sale price can be left blank. Example:<br>pipe goli 5no, pcs, 165, 100<br>aam loha sari ring, pcs, , 600</p>\n    <textarea id=\"importProductText\" style=\"min-height:160px;\" placeholder=\"Name, Unit, Sale price, Stock qty\"></textarea>\n    <div class=\"sheet-actions\">\n      <button class=\"btn-skip\" id=\"cancelProductImport\">Cancel</button>\n      <button class=\"btn-save\" id=\"saveProductImport\">Import</button>\n    </div>\n  </div></div>`;\n  document.getElementById(\"cancelProductImport\").addEventListener(\"click\", ()=> layer.innerHTML=\"\");\n  document.getElementById(\"saveProductImport\").addEventListener(\"click\", async ()=>{\n    const text = document.getElementById(\"importProductText\").value;\n    const lines = text.split(\"\\n\").map(l=>l.trim()).filter(Boolean);\n    if(lines.length===0){ showToast(\"Paste at least one line\"); return; }\n    let added = 0, updated = 0;\n    for(const line of lines){\n      const parts = line.split(\",\").map(p=>p.trim());\n      if(!parts[0]) continue;\n      const name = parts[0];\n      const unit = parts[1] || \"pcs\";\n      const salePrice = parseFloat(parts[2]) || 0;\n      const stock = parseFloat(parts[3]) || 0;\n      let prod = products.find(p => p.name.toLowerCase() === name.toLowerCase());\n      if(!prod){\n        prod = {id: Date.now().toString(36)+Math.random().toString(36).slice(2,7), name, unit, salePrice, stock};\n        products.push(prod);\n        added++;\n      } else {\n        prod.stock = Math.round((prod.stock + stock)*100)/100;\n        updated++;\n      }\n    }\n    await storeSet(\"pos-products\", products);\n    layer.innerHTML = \"\";\n    showToast(`Imported ${added} new${updated ? \", \"+updated+\" updated\" : \"\"}`);\n    renderStock(); renderPOS();\n  });\n}\nfunction openManageProductsSheet(){\n  const layer = document.getElementById(\"sheetLayer\");\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>Manage products</h2>\n    <p>Update sale price or remove a product.</p>\n    <div id=\"manageProdList\"></div>\n    <div class=\"sheet-actions\" style=\"margin-top:16px;\"><button class=\"btn-skip\" id=\"closeManageProd\" style=\"flex:1;\">Done</button></div>\n  </div></div>`;\n  renderManageProdList();\n  document.getElementById(\"closeManageProd\").addEventListener(\"click\", ()=>{ layer.innerHTML=\"\"; renderStock(); renderPOS(); });\n}\nfunction renderManageProdList(){\n  const list = document.getElementById(\"manageProdList\");\n  if(products.length===0){ list.innerHTML = '<div class=\"empty-note\">No products yet</div>'; return; }\n  list.innerHTML = products.map(p=>`\n    <div class=\"product-row-manage\">\n      <div style=\"flex:1;\">\n        <div style=\"font-weight:600;\">${escapeHtml(p.name)} <span style=\"font-weight:400;color:var(--ink-soft);font-size:12.5px;\">(${escapeHtml(p.unit||'pcs')})</span></div>\n        <input type=\"number\" data-id=\"${p.id}\" class=\"edit-price\" value=\"${p.salePrice}\" style=\"width:100px; margin-top:6px; border:1px solid var(--line); border-radius:8px; padding:7px;\">\n      </div>\n      <div class=\"manage-actions\"><button data-id=\"${p.id}\" data-act=\"del\">Remove</button></div>\n    </div>`).join(\"\");\n  list.querySelectorAll(\".edit-price\").forEach(inp=>{\n    inp.addEventListener(\"change\", async ()=>{\n      const prod = products.find(p=>p.id===inp.dataset.id);\n      const val = parseFloat(inp.value);\n      if(prod && !isNaN(val)){ prod.salePrice = val; await storeSet(\"pos-products\", products); showToast(\"Price updated\"); }\n    });\n  });\n  list.querySelectorAll(\"[data-act='del']\").forEach(btn=>{\n    btn.addEventListener(\"click\", async ()=>{\n      await sbDeleteRow(\"shop_products\", btn.dataset.id);\n      products = products.filter(p=>p.id!==btn.dataset.id);\n      renderManageProdList();\n    });\n  });\n}\n\n/* --- Ledger tab: Khata + Suppliers + Cash Book --- */\nfunction renderLedger(){\n  const el = document.getElementById(\"ledgerTab\");\n  el.innerHTML = `\n    <div class=\"subtab-row\">\n      <button class=\"subtab-btn ${ledgerView==='khata'?'active':''}\" id=\"subKhata\">Customers</button>\n      <button class=\"subtab-btn ${ledgerView==='suppliers'?'active':''}\" id=\"subSuppliers\">Suppliers</button>\n      <button class=\"subtab-btn ${ledgerView==='cash'?'active':''}\" id=\"subCash\">Cash Book</button>\n    </div>\n    <div id=\"ledgerBody\"></div>\n    <div class=\"fab-wrap\"><div class=\"fab-inner\"><button class=\"fab\" id=\"ledgerFab\">+</button></div></div>\n  `;\n  document.getElementById(\"subKhata\").addEventListener(\"click\", ()=>{ ledgerView=\"khata\"; renderLedger(); });\n  document.getElementById(\"subSuppliers\").addEventListener(\"click\", ()=>{ ledgerView=\"suppliers\"; renderLedger(); });\n  document.getElementById(\"subCash\").addEventListener(\"click\", ()=>{ ledgerView=\"cash\"; renderLedger(); });\n  document.getElementById(\"ledgerFab\").addEventListener(\"click\", ()=>{\n    if(ledgerView===\"khata\") openNewCreditSheet();\n    else if(ledgerView===\"suppliers\") openNewSupplierCreditSheet();\n    else openCashEntrySheet();\n  });\n  if(ledgerView===\"khata\") renderKhataBody();\n  else if(ledgerView===\"suppliers\") renderSuppliersBody();\n  else renderCashBody();\n}\nfunction renderKhataBody(){\n  const body = document.getElementById(\"ledgerBody\");\n  const totalOwed = customers.reduce((s,c)=> s + Math.max(0, customerBalance(c.id)), 0);\n  const importLink = `<div style=\"text-align:right; margin-bottom:8px;\"><button class=\"gear-btn\" style=\"font-size:13px; text-decoration:underline;\" id=\"importCustBtn\">⬆ Import list</button></div>`;\n  if(customers.length===0){\n    body.innerHTML = `\n      ${importLink}\n      <div class=\"card\">\n        <div class=\"today-total\"><span class=\"label\">Total credit out</span><span class=\"value\">Rs ${totalOwed.toFixed(0)}</span></div>\n      </div>\n      <div class=\"card\"><div class=\"empty-note\">No customers yet — tap + to add a credit entry, or import a list</div></div>`;\n    document.getElementById(\"importCustBtn\").addEventListener(\"click\", ()=> openImportSheet(\"customer\"));\n    return;\n  }\n  const sorted = customers.slice().sort((a,b)=> customerBalance(b.id) - customerBalance(a.id));\n  body.innerHTML = `\n    ${importLink}\n    <div class=\"card\">\n      <div class=\"today-total\"><span class=\"label\">Total credit out</span><span class=\"value\">Rs ${totalOwed.toFixed(0)}</span></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"section-title\" style=\"margin-top:0;\">Customers</div>\n      <div id=\"customerList\"></div>\n    </div>`;\n  document.getElementById(\"importCustBtn\").addEventListener(\"click\", ()=> openImportSheet(\"customer\"));\n  document.getElementById(\"customerList\").innerHTML = sorted.map(c=>{\n    const bal = customerBalance(c.id);\n    return `<div class=\"customer-row\" data-id=\"${c.id}\">\n      <div>\n        <div class=\"cname\">${escapeHtml(c.name)}</div>\n        ${c.phone ? `<div class=\"cphone\">${escapeHtml(c.phone)}</div>` : ''}\n      </div>\n      <div class=\"cbal ${bal>0?'owe':'clear'}\">${bal>0 ? 'Owes Rs '+bal.toFixed(0) : 'Settled'}</div>\n    </div>`;\n  }).join(\"\");\n  document.querySelectorAll(\".customer-row\").forEach(row=>{\n    row.addEventListener(\"click\", ()=>openCustomerSheet(row.dataset.id));\n  });\n}\nfunction renderSuppliersBody(){\n  const body = document.getElementById(\"ledgerBody\");\n  const totalOwed = suppliers.reduce((s,sup)=> s + Math.max(0, supplierBalance(sup.id)), 0);\n  const importLink = `<div style=\"text-align:right; margin-bottom:8px;\"><button class=\"gear-btn\" style=\"font-size:13px; text-decoration:underline;\" id=\"importSupBtn\">⬆ Import list</button></div>`;\n  if(suppliers.length===0){\n    body.innerHTML = `\n      ${importLink}\n      <div class=\"card\">\n        <div class=\"today-total\"><span class=\"label\">Total you owe</span><span class=\"value\">Rs ${totalOwed.toFixed(0)}</span></div>\n      </div>\n      <div class=\"card\"><div class=\"empty-note\">No suppliers yet — tap + to add a credit entry, import a list, or use \"Partial\"/\"Full credit\" when restocking</div></div>`;\n    document.getElementById(\"importSupBtn\").addEventListener(\"click\", ()=> openImportSheet(\"supplier\"));\n    return;\n  }\n  const sorted = suppliers.slice().sort((a,b)=> supplierBalance(b.id) - supplierBalance(a.id));\n  body.innerHTML = `\n    ${importLink}\n    <div class=\"card\">\n      <div class=\"today-total\"><span class=\"label\">Total you owe</span><span class=\"value\">Rs ${totalOwed.toFixed(0)}</span></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"section-title\" style=\"margin-top:0;\">Suppliers</div>\n      <div id=\"supplierList\"></div>\n    </div>`;\n  document.getElementById(\"importSupBtn\").addEventListener(\"click\", ()=> openImportSheet(\"supplier\"));\n  document.getElementById(\"supplierList\").innerHTML = sorted.map(s=>{\n    const bal = supplierBalance(s.id);\n    return `<div class=\"customer-row\" data-id=\"${s.id}\">\n      <div>\n        <div class=\"cname\">${escapeHtml(s.name)}</div>\n        ${s.phone ? `<div class=\"cphone\">${escapeHtml(s.phone)}</div>` : ''}\n      </div>\n      <div class=\"cbal ${bal>0?'owe':'clear'}\">${bal>0 ? 'You owe Rs '+bal.toFixed(0) : 'Settled'}</div>\n    </div>`;\n  }).join(\"\");\n  document.querySelectorAll(\"#supplierList .customer-row\").forEach(row=>{\n    row.addEventListener(\"click\", ()=>openSupplierSheet(row.dataset.id));\n  });\n}\nfunction openImportSheet(kind){\n  const layer = document.getElementById(\"sheetLayer\");\n  const label = kind === \"customer\" ? \"customers\" : \"suppliers\";\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>Import ${label}</h2>\n    <p>One per line: <strong>Name, Phone (optional), Balance</strong>. Balance is what they currently owe. Example:<br>Subhan H/W, 03001234567, 808100<br>Mehboob H/W, , 399200</p>\n    <textarea id=\"importText\" style=\"min-height:160px;\" placeholder=\"Name, Phone, Balance\"></textarea>\n    <div class=\"sheet-actions\">\n      <button class=\"btn-skip\" id=\"cancelImport\">Cancel</button>\n      <button class=\"btn-save\" id=\"saveImport\">Import</button>\n    </div>\n  </div></div>`;\n  document.getElementById(\"cancelImport\").addEventListener(\"click\", ()=> layer.innerHTML=\"\");\n  document.getElementById(\"saveImport\").addEventListener(\"click\", async ()=>{\n    const text = document.getElementById(\"importText\").value;\n    const lines = text.split(\"\\n\").map(l=>l.trim()).filter(Boolean);\n    if(lines.length===0){ showToast(\"Paste at least one line\"); return; }\n    let added = 0, updated = 0;\n    const list = kind === \"customer\" ? customers : suppliers;\n    const txArr = kind === \"customer\" ? khataTx : supplierTx;\n    for(const line of lines){\n      const parts = line.split(\",\").map(p=>p.trim());\n      if(!parts[0]) continue;\n      const name = parts[0];\n      let phone = \"\", balance = 0;\n      if(parts.length === 2){ balance = parseFloat(parts[1]) || 0; }\n      else if(parts.length >= 3){ phone = parts[1]; balance = parseFloat(parts[2]) || 0; }\n      let party = list.find(p => p.name.toLowerCase() === name.toLowerCase());\n      if(!party){\n        party = {id: Date.now().toString(36)+Math.random().toString(36).slice(2,7), name, phone};\n        list.push(party);\n        added++;\n      } else {\n        updated++;\n      }\n      if(balance > 0){\n        const entry = {id: Date.now().toString(36)+Math.random().toString(36).slice(2,7), type:\"credit\", amount: balance, note:\"Opening balance (imported)\", date: new Date().toISOString()};\n        if(kind === \"customer\") entry.customerId = party.id; else entry.supplierId = party.id;\n        txArr.push(entry);\n      }\n    }\n    if(kind === \"customer\"){\n      await storeSet(\"khata-customers\", customers);\n      await storeSet(\"khata-tx\", khataTx);\n    } else {\n      await storeSet(\"khata-suppliers\", suppliers);\n      await storeSet(\"supplier-tx\", supplierTx);\n    }\n    layer.innerHTML = \"\";\n    showToast(`Imported ${added} new${updated ? \", \"+updated+\" matched existing\" : \"\"}`);\n    renderLedger();\n  });\n}\nfunction openNewSupplierCreditSheet(){\n  const layer = document.getElementById(\"sheetLayer\");\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>New supplier credit</h2>\n    <p>Record stock or goods you took from a supplier on credit.</p>\n    <span class=\"form-label\">Supplier</span>\n    <select id=\"supCreditSupplier\" class=\"select-field\">\n      <option value=\"__new__\">+ New supplier</option>\n      ${suppliers.map(s=>`<option value=\"${s.id}\">${escapeHtml(s.name)}</option>`).join(\"\")}\n    </select>\n    <div id=\"newSupplierFields\" style=\"display:${suppliers.length===0?'block':'none'};\">\n      <span class=\"form-label\">Name</span>\n      <input type=\"text\" id=\"newSupName2\" placeholder=\"Supplier name\">\n      <span class=\"form-label\">Phone (optional)</span>\n      <input type=\"text\" id=\"newSupPhone2\" placeholder=\"e.g. 03001234567\">\n    </div>\n    <span class=\"form-label\">Amount</span>\n    ${calcFieldHtml(\"supCreditAmount\", \"e.g. 15000\")}\n    <span class=\"form-label\">Bill / reference no. (optional)</span>\n    <input type=\"text\" id=\"supCreditBillNo\" placeholder=\"e.g. INV-2201\">\n    <span class=\"form-label\">Note (optional)</span>\n    <input type=\"text\" id=\"supCreditNote\" placeholder=\"e.g. 5 bags cement\">\n    <div class=\"sheet-actions\">\n      <button class=\"btn-skip\" id=\"cancelSupCredit\">Cancel</button>\n      <button class=\"btn-save\" id=\"saveSupCredit\">Save</button>\n    </div>\n  </div></div>`;\n  const sel = document.getElementById(\"supCreditSupplier\");\n  wireNewCustomerFields(sel, \"newSupplierFields\");\n  document.getElementById(\"cancelSupCredit\").addEventListener(\"click\", ()=> layer.innerHTML=\"\");\n  document.getElementById(\"saveSupCredit\").addEventListener(\"click\", async ()=>{\n    const amount = parseFloat(document.getElementById(\"supCreditAmount\").value);\n    if(isNaN(amount) || amount<=0){ showToast(\"Enter a valid amount\"); return; }\n    let supplierId = sel.value;\n    if(supplierId === \"__new__\"){\n      const name = document.getElementById(\"newSupName2\").value.trim();\n      if(!name){ showToast(\"Enter supplier name\"); return; }\n      const phone = document.getElementById(\"newSupPhone2\").value.trim();\n      const newSup = {id: Date.now().toString(36), name, phone};\n      suppliers.push(newSup);\n      supplierId = newSup.id;\n      await storeSet(\"khata-suppliers\", suppliers);\n    }\n    supplierTx.push({id: Date.now().toString(36)+Math.random().toString(36).slice(2,6), supplierId, type:\"credit\", amount, note: document.getElementById(\"supCreditNote\").value.trim(), ref: document.getElementById(\"supCreditBillNo\").value.trim(), date: new Date().toISOString()});\n    await storeSet(\"supplier-tx\", supplierTx);\n    layer.innerHTML = \"\";\n    showToast(\"Credit recorded\");\n    renderLedger();\n  });\n}\nfunction openSupplierSheet(supplierId){\n  const layer = document.getElementById(\"sheetLayer\");\n  const sup = suppliers.find(s=>s.id===supplierId);\n  if(!sup) return;\n  const bal = supplierBalance(supplierId);\n  const history = supplierTx.filter(t=>t.supplierId===supplierId).sort((a,b)=> new Date(b.date)-new Date(a.date));\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>${escapeHtml(sup.name)}</h2>\n    <p>${bal>0 ? 'You owe Rs '+bal.toFixed(0) : 'Settled up'}${sup.phone ? ' · '+escapeHtml(sup.phone) : ''}</p>\n    <div class=\"sheet-actions\" style=\"margin-bottom:16px;\">\n      <button class=\"btn-save\" id=\"recordSupplierPayment\" style=\"flex:1;\">Record payment made</button>\n    </div>\n    <div class=\"section-title\" style=\"margin-top:0;\">History</div>\n    <div id=\"supHistory\"></div>\n    <div class=\"sheet-actions\" style=\"margin-top:16px;\"><button class=\"btn-skip\" id=\"closeSup\" style=\"flex:1;\">Close</button></div>\n  </div></div>`;\n  const hist = document.getElementById(\"supHistory\");\n  hist.innerHTML = history.length===0 ? '<div class=\"empty-note\">No entries yet</div>' : history.map(t=>`\n    <div class=\"tx-row\" data-tx=\"${t.id}\" style=\"cursor:pointer;\">\n      <span>${t.type==='credit' ? 'Bought on credit' : 'Paid'}${t.note ? ' — '+escapeHtml(t.note) : ''}${t.ref ? ' ('+escapeHtml(t.ref)+')' : ''}<span style=\"color:var(--ink-soft);\"> ›</span></span>\n      <span style=\"color:${t.type==='credit'?'var(--danger)':'var(--forest-deep)'}; font-weight:600;\">${t.type==='credit'?'+':'−'} Rs ${t.amount.toFixed(0)}</span>\n    </div>`).join(\"\");\n  hist.querySelectorAll(\".tx-row[data-tx]\").forEach(row=>{\n    row.addEventListener(\"click\", ()=> openTxDetailSheet(\"supplier\", row.dataset.tx, supplierId));\n  });\n  document.getElementById(\"closeSup\").addEventListener(\"click\", ()=>{ layer.innerHTML=\"\"; renderLedger(); });\n  document.getElementById(\"recordSupplierPayment\").addEventListener(\"click\", ()=> openRecordSupplierPaymentSheet(supplierId));\n}\nfunction openRecordSupplierPaymentSheet(supplierId){\n  const layer = document.getElementById(\"sheetLayer\");\n  const sup = suppliers.find(s=>s.id===supplierId);\n  const bal = supplierBalance(supplierId);\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>Record payment</h2>\n    <p>You currently owe ${escapeHtml(sup.name)} Rs ${bal.toFixed(0)}.</p>\n    <span class=\"form-label\">Amount paid</span>\n    ${calcFieldHtml(\"supPaymentAmount\", \"e.g. 5000\")}\n    <div class=\"sheet-actions\">\n      <button class=\"btn-skip\" id=\"cancelSupPayment\">Cancel</button>\n      <button class=\"btn-save\" id=\"saveSupPayment\">Save</button>\n    </div>\n  </div></div>`;\n  document.getElementById(\"cancelSupPayment\").addEventListener(\"click\", ()=>{ layer.innerHTML=\"\"; openSupplierSheet(supplierId); });\n  document.getElementById(\"saveSupPayment\").addEventListener(\"click\", async ()=>{\n    const amount = parseFloat(document.getElementById(\"supPaymentAmount\").value);\n    if(isNaN(amount) || amount<=0){ showToast(\"Enter a valid amount\"); return; }\n    supplierTx.push({id: Date.now().toString(36)+Math.random().toString(36).slice(2,6), supplierId, type:\"payment\", amount, note:\"\", date: new Date().toISOString()});\n    await storeSet(\"supplier-tx\", supplierTx);\n    cashbook.push({id: Date.now().toString(36)+Math.random().toString(36).slice(2,6), type:\"out\", amount, note:\"Payment made\", date: new Date().toISOString(), partyType:\"supplier\", partyId:supplierId, partyName:sup.name});\n    await storeSet(\"cashbook\", cashbook);\n    layer.innerHTML = \"\";\n    showToast(\"Payment recorded\");\n    renderLedger();\n  });\n}\nfunction renderCashBody(){\n  const body = document.getElementById(\"ledgerBody\");\n  const balance = cashInHand();\n  const recent = cashbook.slice().sort((a,b)=> new Date(b.date)-new Date(a.date)).slice(0,30);\n  body.innerHTML = `\n    <div class=\"card\">\n      <div class=\"today-total\"><span class=\"label\">Cash in hand</span><span class=\"value\">Rs ${balance.toFixed(0)}</span></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"section-title\" style=\"margin-top:0;\">Recent entries</div>\n      <div id=\"cashList\"></div>\n    </div>`;\n  const list = document.getElementById(\"cashList\");\n  if(recent.length===0){\n    list.innerHTML = '<div class=\"empty-note\">No entries yet — tap + to add one</div>';\n  } else {\n    list.innerHTML = recent.map(e=>`\n      <div class=\"cash-row\">\n        <div>\n          <div>${escapeHtml(e.note || (e.type==='in' ? 'Cash in' : 'Cash out'))}${e.partyName ? ` <span style=\"color:var(--ink-soft); font-weight:400;\">— ${escapeHtml(e.partyName)}</span>` : ''}</div>\n          <div class=\"cnote\">${new Date(e.date).toLocaleDateString()} · ${fmtTimeLabel(e.date)}</div>\n        </div>\n        <div class=\"camt ${e.type}\">${e.type==='in'?'+':'−'} Rs ${e.amount.toFixed(0)}</div>\n      </div>`).join(\"\");\n  }\n}\nfunction customerSelectOptions(){\n  return customers.map(c=>`<option value=\"${c.id}\">${escapeHtml(c.name)}</option>`).join(\"\");\n}\nfunction wireNewCustomerFields(sel, wrapId){\n  sel.addEventListener(\"change\", ()=>{\n    document.getElementById(wrapId).style.display = sel.value === \"__new__\" ? \"block\" : \"none\";\n  });\n}\nfunction openNewCreditSheet(){\n  const layer = document.getElementById(\"sheetLayer\");\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>New credit entry</h2>\n    <p>Record goods or money given on credit (not through a bill).</p>\n    <span class=\"form-label\">Customer</span>\n    <select id=\"creditCustomer\" class=\"select-field\">\n      <option value=\"__new__\">+ New customer</option>\n      ${customerSelectOptions()}\n    </select>\n    <div id=\"newCustomerFields\" style=\"display:${customers.length===0?'block':'none'};\">\n      <span class=\"form-label\">Name</span>\n      <input type=\"text\" id=\"newCustName\" placeholder=\"Customer name\">\n      <span class=\"form-label\">Phone (optional, for WhatsApp reminders)</span>\n      <input type=\"text\" id=\"newCustPhone\" placeholder=\"e.g. 03001234567\">\n    </div>\n    <span class=\"form-label\">Amount</span>\n    ${calcFieldHtml(\"creditAmount\", \"e.g. 1500\")}\n    <span class=\"form-label\">Bill / reference no. (optional)</span>\n    <input type=\"text\" id=\"creditBillNo\" placeholder=\"e.g. INV-2201\">\n    <span class=\"form-label\">Note (optional)</span>\n    <input type=\"text\" id=\"creditNote\" placeholder=\"e.g. 2 bags cement\">\n    <div class=\"sheet-actions\">\n      <button class=\"btn-skip\" id=\"cancelCredit\">Cancel</button>\n      <button class=\"btn-save\" id=\"saveCredit\">Save</button>\n    </div>\n  </div></div>`;\n  const sel = document.getElementById(\"creditCustomer\");\n  wireNewCustomerFields(sel, \"newCustomerFields\");\n  document.getElementById(\"cancelCredit\").addEventListener(\"click\", ()=> layer.innerHTML=\"\");\n  document.getElementById(\"saveCredit\").addEventListener(\"click\", async ()=>{\n    const amount = parseFloat(document.getElementById(\"creditAmount\").value);\n    if(isNaN(amount) || amount<=0){ showToast(\"Enter a valid amount\"); return; }\n    let customerId = sel.value;\n    if(customerId === \"__new__\"){\n      const name = document.getElementById(\"newCustName\").value.trim();\n      if(!name){ showToast(\"Enter customer name\"); return; }\n      const phone = document.getElementById(\"newCustPhone\").value.trim();\n      const newCust = {id: Date.now().toString(36), name, phone};\n      customers.push(newCust);\n      customerId = newCust.id;\n      await storeSet(\"khata-customers\", customers);\n    }\n    khataTx.push({id: Date.now().toString(36)+Math.random().toString(36).slice(2,6), customerId, type:\"credit\", amount, note: document.getElementById(\"creditNote\").value.trim(), ref: document.getElementById(\"creditBillNo\").value.trim(), date: new Date().toISOString()});\n    await storeSet(\"khata-tx\", khataTx);\n    layer.innerHTML = \"\";\n    showToast(\"Credit recorded\");\n    renderLedger();\n  });\n}\nfunction openCustomerSheet(customerId){\n  const layer = document.getElementById(\"sheetLayer\");\n  const cust = customers.find(c=>c.id===customerId);\n  if(!cust) return;\n  const bal = customerBalance(customerId);\n  const history = khataTx.filter(t=>t.customerId===customerId).sort((a,b)=> new Date(b.date)-new Date(a.date));\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>${escapeHtml(cust.name)}</h2>\n    <p>${bal>0 ? 'Owes Rs '+bal.toFixed(0) : 'Settled up'}${cust.phone ? ' · '+escapeHtml(cust.phone) : ''}</p>\n    <div class=\"sheet-actions\" style=\"margin-bottom:16px;\">\n      <button class=\"btn-save\" id=\"recordPayment\">Record payment</button>\n      ${cust.phone ? `<a class=\"btn-whatsapp\" id=\"waRemind\" href=\"${waLink(cust.phone, bal>0 ? `Assalam-o-Alaikum ${cust.name}, aap ka humare taraf Rs ${bal.toFixed(0)} baqaya hai. Meharbani farma k jald ada karein. Shukriya.` : `Assalam-o-Alaikum ${cust.name}, shukriya!`)}\" target=\"_blank\" rel=\"noopener\">WhatsApp</a>` : ''}\n    </div>\n    <div class=\"section-title\" style=\"margin-top:0;\">History</div>\n    <div id=\"custHistory\"></div>\n    <div class=\"sheet-actions\" style=\"margin-top:16px;\"><button class=\"btn-skip\" id=\"closeCust\" style=\"flex:1;\">Close</button></div>\n  </div></div>`;\n  const hist = document.getElementById(\"custHistory\");\n  hist.innerHTML = history.length===0 ? '<div class=\"empty-note\">No entries yet</div>' : history.map(t=>`\n    <div class=\"tx-row\" data-tx=\"${t.id}\" style=\"cursor:pointer;\">\n      <span>${t.type==='credit' ? 'Credit given' : 'Payment received'}${t.note ? ' — '+escapeHtml(t.note) : ''}${t.ref ? ' ('+escapeHtml(t.ref)+')' : ''}<span style=\"color:var(--ink-soft);\"> ›</span></span>\n      <span style=\"color:${t.type==='credit'?'var(--danger)':'var(--forest-deep)'}; font-weight:600;\">${t.type==='credit'?'+':'−'} Rs ${t.amount.toFixed(0)}</span>\n    </div>`).join(\"\");\n  hist.querySelectorAll(\".tx-row[data-tx]\").forEach(row=>{\n    row.addEventListener(\"click\", ()=> openTxDetailSheet(\"customer\", row.dataset.tx, customerId));\n  });\n  document.getElementById(\"closeCust\").addEventListener(\"click\", ()=>{ layer.innerHTML=\"\"; renderLedger(); });\n  document.getElementById(\"recordPayment\").addEventListener(\"click\", ()=> openRecordPaymentSheet(customerId));\n}\nfunction openRecordPaymentSheet(customerId){\n  const layer = document.getElementById(\"sheetLayer\");\n  const cust = customers.find(c=>c.id===customerId);\n  const bal = customerBalance(customerId);\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>Record payment</h2>\n    <p>${escapeHtml(cust.name)} currently owes Rs ${bal.toFixed(0)}.</p>\n    <span class=\"form-label\">Amount received</span>\n    ${calcFieldHtml(\"paymentAmount\", \"e.g. 500\")}\n    <div class=\"sheet-actions\">\n      <button class=\"btn-skip\" id=\"cancelPayment\">Cancel</button>\n      <button class=\"btn-save\" id=\"savePayment\">Save</button>\n    </div>\n  </div></div>`;\n  document.getElementById(\"cancelPayment\").addEventListener(\"click\", ()=>{ layer.innerHTML=\"\"; openCustomerSheet(customerId); });\n  document.getElementById(\"savePayment\").addEventListener(\"click\", async ()=>{\n    const amount = parseFloat(document.getElementById(\"paymentAmount\").value);\n    if(isNaN(amount) || amount<=0){ showToast(\"Enter a valid amount\"); return; }\n    khataTx.push({id: Date.now().toString(36)+Math.random().toString(36).slice(2,6), customerId, type:\"payment\", amount, note:\"\", date: new Date().toISOString()});\n    await storeSet(\"khata-tx\", khataTx);\n    cashbook.push({id: Date.now().toString(36)+Math.random().toString(36).slice(2,6), type:\"in\", amount, note:\"Payment received\", date: new Date().toISOString(), partyType:\"customer\", partyId:customerId, partyName:cust.name});\n    await storeSet(\"cashbook\", cashbook);\n    layer.innerHTML = \"\";\n    showToast(\"Payment recorded\");\n    renderLedger();\n  });\n}\nfunction txShareText(kind, tx, party, partyId){\n  const isCust = kind === \"customer\";\n  const isCredit = tx.type === \"credit\";\n  const amt = \"Rs \" + tx.amount.toFixed(0);\n  const dateStr = new Date(tx.date).toLocaleDateString();\n  const bal = isCust ? customerBalance(partyId) : supplierBalance(partyId);\n  const balLine = bal > 0\n    ? (isCust ? `Ab baqaya: Rs ${bal.toFixed(0)}.` : `Ab hum par baqaya: Rs ${bal.toFixed(0)}.`)\n    : \"Hisaab clear hai.\";\n  const line = isCust\n    ? (isCredit ? `Udhaar: ${amt}` : `Jama: ${amt}`)\n    : (isCredit ? `Maal udhaar: ${amt}` : `Adaigi: ${amt}`);\n  return `${party.name} — ${line}${tx.note ? ` (${tx.note})` : \"\"} — ${dateStr}. ${balLine}`;\n}\nfunction openTxDetailSheet(kind, txId, partyId){\n  const layer = document.getElementById(\"sheetLayer\");\n  const isCust = kind === \"customer\";\n  const txArr = isCust ? khataTx : supplierTx;\n  const tx = txArr.find(t=>t.id===txId);\n  if(!tx){ showToast(\"Entry not found\"); return; }\n  const party = (isCust ? customers : suppliers).find(p=>p.id===partyId);\n  const isCredit = tx.type === \"credit\";\n  const typeLabel = isCust\n    ? (isCredit ? \"Credit given\" : \"Payment received\")\n    : (isCredit ? \"Bought on credit\" : \"Payment made\");\n  const d0 = new Date(tx.date);\n  const dateVal = isNaN(d0) ? \"\" : d0.getFullYear()+\"-\"+String(d0.getMonth()+1).padStart(2,\"0\")+\"-\"+String(d0.getDate()).padStart(2,\"0\");\n  const reopenParty = ()=> isCust ? openCustomerSheet(partyId) : openSupplierSheet(partyId);\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>Entry detail</h2>\n    <p>${typeLabel}${tx.billId ? ' · from a bill' : ''} · ${new Date(tx.date).toLocaleString()}</p>\n    <span class=\"form-label\">Amount</span>\n    ${calcFieldHtml(\"txEditAmount\", \"\")}\n    <span class=\"form-label\">Note</span>\n    <input type=\"text\" id=\"txEditNote\" placeholder=\"Note (optional)\">\n    <span class=\"form-label\">Date</span>\n    <input type=\"date\" id=\"txEditDate\">\n    ${tx.billId ? `<p style=\"color:var(--ink-soft);\">This entry came from a bill — changing it here won't change the original bill.</p>` : ''}\n    <div class=\"sheet-actions\">\n      <button class=\"btn-skip\" id=\"txDelete\" style=\"background:var(--danger); color:#fff;\">Delete</button>\n      <button class=\"btn-save\" id=\"txSave\">Save changes</button>\n    </div>\n    ${party && party.phone ? `<a class=\"btn-whatsapp\" style=\"margin-top:10px;\" target=\"_blank\" rel=\"noopener\" href=\"${waLink(party.phone, txShareText(kind, tx, party, partyId))}\">Share on WhatsApp</a>` : ''}\n    <div class=\"sheet-actions\" style=\"margin-top:10px;\"><button class=\"btn-skip\" id=\"txBack\" style=\"flex:1;\">Back</button></div>\n  </div></div>`;\n  document.getElementById(\"txEditAmount\").value = tx.amount;\n  document.getElementById(\"txEditNote\").value = tx.note || \"\";\n  if(dateVal) document.getElementById(\"txEditDate\").value = dateVal;\n\n  document.getElementById(\"txBack\").addEventListener(\"click\", ()=>{ layer.innerHTML=\"\"; reopenParty(); });\n  document.getElementById(\"txSave\").addEventListener(\"click\", async ()=>{\n    const newAmount = parseFloat(document.getElementById(\"txEditAmount\").value);\n    if(isNaN(newAmount) || newAmount<=0){ showToast(\"Enter a valid amount\"); return; }\n    tx.amount = Math.round(newAmount*100)/100;\n    tx.note = document.getElementById(\"txEditNote\").value.trim();\n    const d = document.getElementById(\"txEditDate\").value;\n    if(d) tx.date = new Date(d + \"T12:00:00\").toISOString();\n    await storeSet(isCust ? \"khata-tx\" : \"supplier-tx\", txArr);\n    layer.innerHTML = \"\";\n    showToast(\"Entry updated\");\n    renderLedger();\n    reopenParty();\n  });\n  let armed = false, armTimer = null;\n  const delBtn = document.getElementById(\"txDelete\");\n  delBtn.addEventListener(\"click\", async ()=>{\n    if(!armed){\n      armed = true;\n      delBtn.textContent = \"Tap again to delete\";\n      armTimer = setTimeout(()=>{ armed = false; delBtn.textContent = \"Delete\"; }, 3000);\n      return;\n    }\n    if(armTimer) clearTimeout(armTimer);\n    await sbDeleteRow(isCust ? \"shop_khata_tx\" : \"shop_supplier_tx\", tx.id);\n    if(isCust) khataTx = khataTx.filter(t=>t.id!==tx.id);\n    else supplierTx = supplierTx.filter(t=>t.id!==tx.id);\n    layer.innerHTML = \"\";\n    showToast(\"Entry deleted\");\n    renderLedger();\n    reopenParty();\n  });\n}\nfunction openCashEntrySheet(){\n  const layer = document.getElementById(\"sheetLayer\");\n  layer.innerHTML = `<div class=\"sheet-backdrop\"><div class=\"sheet\">\n    <h2>Add cash entry</h2>\n    <div class=\"subtab-row\">\n      <button type=\"button\" class=\"subtab-btn active\" id=\"cashModeIn\">Cash in</button>\n      <button type=\"button\" class=\"subtab-btn\" id=\"cashModeOut\">Cash out</button>\n    </div>\n    <span class=\"form-label\">Amount</span>\n    ${calcFieldHtml(\"cashAmount\", \"e.g. 2000\")}\n    <span class=\"form-label\">Party (optional)</span>\n    <select id=\"cashParty\" class=\"select-field\">\n      <option value=\"\">No party — general expense/income</option>\n      ${customers.length ? `<optgroup label=\"Customers\">${customers.map(c=>`<option value=\"c:${c.id}\">${escapeHtml(c.name)}</option>`).join(\"\")}</optgroup>` : ''}\n      ${suppliers.length ? `<optgroup label=\"Suppliers\">${suppliers.map(s=>`<option value=\"s:${s.id}\">${escapeHtml(s.name)}</option>`).join(\"\")}</optgroup>` : ''}\n    </select>\n    <span class=\"form-label\">Note</span>\n    <input type=\"text\" id=\"cashNote\" placeholder=\"e.g. Paid shop rent\">\n    <div class=\"sheet-actions\">\n      <button class=\"btn-skip\" id=\"cancelCash\">Cancel</button>\n      <button class=\"btn-save\" id=\"saveCash\">Save</button>\n    </div>\n  </div></div>`;\n  let cashType = \"in\";\n  const inBtn = document.getElementById(\"cashModeIn\");\n  const outBtn = document.getElementById(\"cashModeOut\");\n  inBtn.addEventListener(\"click\", ()=>{ cashType=\"in\"; inBtn.classList.add(\"active\"); outBtn.classList.remove(\"active\"); });\n  outBtn.addEventListener(\"click\", ()=>{ cashType=\"out\"; outBtn.classList.add(\"active\"); inBtn.classList.remove(\"active\"); });\n  document.getElementById(\"cancelCash\").addEventListener(\"click\", ()=> layer.innerHTML=\"\");\n  document.getElementById(\"saveCash\").addEventListener(\"click\", async ()=>{\n    const amount = parseFloat(document.getElementById(\"cashAmount\").value);\n    if(isNaN(amount) || amount<=0){ showToast(\"Enter a valid amount\"); return; }\n    const partyVal = document.getElementById(\"cashParty\").value;\n    let partyType = null, partyId = null, partyName = null;\n    if(partyVal){\n      const [kind, id] = partyVal.split(\":\");\n      partyType = kind === \"c\" ? \"customer\" : \"supplier\";\n      const list = kind === \"c\" ? customers : suppliers;\n      const found = list.find(x=>x.id===id);\n      if(found){ partyId = found.id; partyName = found.name; }\n    }\n    cashbook.push({id: Date.now().toString(36)+Math.random().toString(36).slice(2,6), type: cashType, amount, note: document.getElementById(\"cashNote\").value.trim(), date: new Date().toISOString(), partyType, partyId, partyName});\n    await storeSet(\"cashbook\", cashbook);\n    layer.innerHTML = \"\";\n    showToast(\"Entry saved\");\n    renderLedger();\n  });\n}\n\n/* ---------- Reminders (while page is open) ---------- */\nlet notifiedToday = {};\nfunction checkReminders(){\n  const now = new Date();\n  const hm = String(now.getHours()).padStart(2,\"0\")+\":\"+String(now.getMinutes()).padStart(2,\"0\");\n  ROUTINE.forEach(sec => sec.items.forEach(item=>{\n    if(item.time === hm && !notifiedToday[item.id]){\n      notifiedToday[item.id] = true;\n      fireReminder(item.name);\n    }\n  }));\n}\nfunction fireReminder(name){\n  showToast(\"Reminder: \" + name);\n  if(window.Notification && Notification.permission === \"granted\"){\n    try{ new Notification(\"Time for: \" + name); }catch(e){}\n  }\n}\nsetInterval(checkReminders, 20000);\ndocument.getElementById(\"notifyBtn\").addEventListener(\"click\", async ()=>{\n  if(window.Notification){\n    const perm = await Notification.requestPermission();\n    if(perm === \"granted\"){ document.getElementById(\"notifyBanner\").style.display = \"none\"; showToast(\"Notifications on\"); }\n  }\n});\nif(window.Notification && Notification.permission === \"default\"){\n  document.getElementById(\"notifyBanner\").style.display = \"block\";\n}\n\n/* ---------- Tabs ---------- */\ndocument.querySelectorAll(\".nav-btn\").forEach(btn=>{\n  btn.addEventListener(\"click\", ()=>{\n    document.querySelectorAll(\".nav-btn\").forEach(b=>b.classList.remove(\"active\"));\n    btn.classList.add(\"active\");\n    const tab = btn.dataset.tab;\n    document.getElementById(\"workTab\").style.display = tab === \"work\" ? \"block\" : \"none\";\n    document.getElementById(\"routineTab\").style.display = tab === \"routine\" ? \"block\" : \"none\";\n    document.getElementById(\"salesTab\").style.display = tab === \"sales\" ? \"block\" : \"none\";\n    document.getElementById(\"stockTab\").style.display = tab === \"stock\" ? \"block\" : \"none\";\n    document.getElementById(\"ledgerTab\").style.display = tab === \"ledger\" ? \"block\" : \"none\";\n    const titles = {work:\"Work\", routine:\"Today's routine\", sales:\"Sales\", stock:\"Stock\", ledger:\"Ledger\"};\n    document.getElementById(\"pageTitle\").textContent = titles[tab];\n  });\n});\n\nasync function seedDemoData(){\n  const alreadySeeded = customers.length > 0 || suppliers.length > 0 || products.length > 0;\n  if(alreadySeeded) return;\n\n  const custData = [\n    [\"M.A H/w\", 282914],\n    [\"Mehboob H/W Saif Bh\", 399205],\n    [\"Irfan Ahmad Nwa\", 298800],\n    [\"Nadeem H/w Guj\", 18960],\n    [\"Subhan H/W\", 808145],\n    [\"Azeem H/w Guj\", 52300],\n    [\"Ali Pipe H/w\", 23906],\n  ];\n  const supData = [\n    [\"Bhai\", 1381257.32],\n    [\"Hunana Box Maker\", 23478],\n    [\"Amjad Silver Dhlai\", 38644],\n    [\"Abdullah\", 260029.02],\n    [\"Billo Bhai\", 6401.66],\n    [\"Mazer Sorak Mose\", 36756.45],\n    [\"mal ksai\", 274],\n    [\"Asim Mal Ksai\", 1500],\n    [\"Umer Fectory\", 5100],\n  ];\n  const prodData = [\n    [\"pipe goli 5no\", \"pcs\", 165, 100],\n    [\"aam loha sari ring\", \"pcs\", 0, 600],\n    [\"degi T lacer\", \"pcs\", 0, 1250],\n    [\"double T wazni\", \"pcs\", 0, 750],\n    [\"degi silver T\", \"pcs\", 0, 2160],\n  ];\n\n  for(const [name, balance] of custData){\n    const c = {id: Date.now().toString(36)+Math.random().toString(36).slice(2,7), name, phone:\"\"};\n    customers.push(c);\n    khataTx.push({id: Date.now().toString(36)+Math.random().toString(36).slice(2,7), customerId:c.id, type:\"credit\", amount:balance, note:\"Opening balance (imported from Digikhata)\", date:new Date().toISOString()});\n  }\n  for(const [name, balance] of supData){\n    const s = {id: Date.now().toString(36)+Math.random().toString(36).slice(2,7), name, phone:\"\"};\n    suppliers.push(s);\n    supplierTx.push({id: Date.now().toString(36)+Math.random().toString(36).slice(2,7), supplierId:s.id, type:\"credit\", amount:balance, note:\"Opening balance (imported from Digikhata)\", date:new Date().toISOString()});\n  }\n  for(const [name, unit, price, stock] of prodData){\n    products.push({id: Date.now().toString(36)+Math.random().toString(36).slice(2,7), name, unit, salePrice:price, stock});\n  }\n\n  await sbSyncSimple(\"shop_customers\", customers);\n  await sbSyncSimple(\"shop_suppliers\", suppliers);\n  await sbSyncProducts(products);\n  await sbSyncKhataTx(khataTx);\n  await sbSyncSupplierTx(supplierTx);\n}\n\ndocument.getElementById(\"dayLabel\").textContent = new Date().toLocaleDateString([], {weekday:'long', month:'long', day:'numeric'});\n\nasync function startApp(){\n  showApp();\n  loadWork();\n  loadRoutine();\n  await loadInventory();\n  await loadLedger();\n  // seedDemoData() intentionally not called — demo data is kept dormant (see function below).\n  renderPOS();\n  renderStock();\n  renderLedger();\n}\n\n(async function boot(){\n  const {data:{session}} = await sb.auth.getSession();\n  if(session){\n    await startApp();\n  } else {\n    showAuthScreen();\n  }\n  sb.auth.onAuthStateChange((event, session)=>{\n    if(event === \"SIGNED_IN\" && document.getElementById(\"app\").style.display === \"none\"){\n      startApp();\n    }\n    if(event === \"SIGNED_OUT\"){\n      showAuthScreen();\n    }\n  });\n})();\n</script>\n</body>\n</html>\n";

Deno.serve(async (req: Request) => {
  return new Response(HTML, {
    headers: {
      "Content-Type": "text/html; charset=utf-8",
    },
  });
});
